// Üretilen dosya: tool/ozgun/uret.py. Tarih · Anadolu uygarlıkları, Anadolu beylikleri ve Türkiye Selçuklu şehir-ticaret hayatı (Hitit, Urartu, Frig, Lidya, İyonya, beylikler, kervansaraylar, Ahilik) (zor).
const ozHistory15Zor = <(String, String, List<String>, String)>[
  ('Hititlerin Anadolu\'da hem Mezopotamya kökenli çivi yazısını hem de kendilerine özgü Luvi hiyeroglif yazısını eş zamanlı kullanmalarında belirleyici ayrım ne olmuştur?', 'Çivi yazısının devlet arşivlerinde, hiyeroglifin ise anıtsal kaya yazıtları ve mühürlerde tercih edilmesi', ['Çivi yazısının yalnızca din adamlarına, hiyeroglifin ise asker sınıfına öğretilmesi', 'Hiyeroglifin gizli istihbarat belgelerinde, çivi yazısının ise ticaret senetlerinde kullanılması', 'Eski Krallık\'ta hiyeroglif kullanılırken İmparatorluk devrinde tamamen çivi yazısına geçilmesi'], 'Hititler kil tablet arşivlerinde Akad/Hitit çivi yazısını kullanırken, herkesin gördüğü açık hava kaya anıtlarında ve mühürlerde Luvi hiyerogliflerini kullanmıştır.'),
  ('Urartu maden ustalarının ürettiği ve Etrüsk ile Yunan tapınaklarına kadar ihraç edilen tunç kazanların ağız kenarlarında sıkça görülen kanatlı insan başlı kuş figürlerine arkeolojide ne ad verilir?', 'Siren eklentisi', ['Sfenks sütunu', 'Medusa maskı', 'Minotaur kabartması'], 'Urartu tunç kazanlarının kenarlarına perçinlenen kanatlı ve insan başlı kuş figürleri (siren) ile boğa başları, Urartu metal sanatı ihracatının simgesidir.'),
  ('Çorum Ortaköy\'de yürütülen kazılarda binlerce çivi yazılı tablet arşiviyle ortaya çıkarılan ve bir dönem Hititlere idari-dini merkezlik yapan antik kent hangisidir?', 'Şapinuva', ['Tuşpa', 'Gordion', 'Sardes'], 'Çorum\'un Ortaköy ilçesindeki Şapinuva, Hitit İmparatorluk döneminin en önemli askeri, dini ve idari merkezlerinden biridir.'),
  ('Urartu nekropollerinde hem iskeletlerin yatırıldığı oda mezarlara hem de yakılan ceset küllerinin konulduğu pişmiş toprak kaplara (urne) aynı mezarlıkta rastlanması nasıl yorumlanır?', 'İnhumasyon ve kremasyon ölü gömme geleneklerinin bir arada uygulandığı biçiminde', ['Salgın hastalık dönemlerinde tüm mezarlıkların ateşe verildiği şeklinde', 'Yabancı paralı askerlerin yerli halktan ayrı kalelere gömüldüğü biçiminde', 'Tek tanrılı inanca geçişle birlikte mezar hediyelerinin yasaklandığı şeklinde'], 'Urartularda hem cesedi gömme (inhumasyon) hem de yakıp küllerini urne kaplarına koyma (kremasyon) adetleri eş zamanlı olarak uygulanmıştır.'),
  ('Osmaniye\'nin Kadirli ilçesindeki Karatepe-Aslantaş Açık Hava Müzesi\'nde bulunan çift dilli (Fenikece ve Luvi hiyeroglifi) yazıtların bilim dünyası açısından en önemli katkısı ne olmuştur?', 'Anadolu hiyeroglif yazısının kesin olarak çözülmesini sağlaması', ['Urartu çivi yazısındaki ticari sayı sistemini açıklaması', 'Sümer tufan efsanesinin en eski nüshasını barındırması', 'Mısır firavun sülalelerinin kronolojik listesini vermesi'], 'Kral Azatiwatas\'a ait Karatepe çift dilli yazıtları, bilinen Fenike alfabesi yardımıyla Luvi (Hitit) hiyerogliflerinin okunmasında kilit rol oynamıştır.'),
  ('Hitit saray teşkilatında kral öldüğünde mevcut Tavananna hayattaysa yeni kralın eşinin hemen bu unvanı alamaması hangi idari kuraldan kaynaklanmaktadır?', 'Tavananna makamının kaydıhayat şartıyla ölümüne dek sürdürülmesi', ['Yeni kraliçenin en az on yıl başrahibelik stajı yapması zorunluluğu', 'Unvanın yalnızca Babil hanedanından gelen prenseslere verilmesi', 'Pankuş meclisinin kraliçe seçimi için beş yıl bekleme şartı koşması'], 'Tavananna unvanı kral ölse dahi yaşayan ana kraliçede kalır; yeni kralın eşi ancak önceki Tavananna öldüğünde bu unvanı devralabilirdi.'),
  ('Urartu kalelerinin inşasında harç kullanılmaksızın dev boyutlu düzgün kesilmiş veya çokgen taş blokların birbirine kenetlenmesiyle oluşturulan duvar tekniğine ne ad verilir?', 'Kiklopik taş işçiliği', ['Opus reticulatum', 'Ahşap karkas dolgu', 'Sırlı kerpiç örgü'], 'Urartular ve Hititler sur mimarisinde harçsız iri kaya bloklarının ustalıkla birleştirildiği kiklopik duvar tekniğini başarıyla uygulamışlardır.'),
  ('Hitit medeni hukukunda evlilik birliğinin kurulması sırasında damat ailesinin gelin tarafına sunduğu ve evliliğin hukuki geçerliliğini pekiştiren başlık/hediye bedeline ne ad verilirdi?', 'Kuşata', ['Drahoma', 'Tapates', 'Şehir harcı'], 'Hitit kanunlarında erkeğin kız ailesine verdiği \'kuşata\' adlı evlilik bedeli, resmi nikâh akdinin temel unsurlarından biriydi.'),
  ('Van il merkezinde sarp bir kayalığa oyulmuş kör bir kapı görünümünde olan ve üzerinde Urartu panteonundaki tüm tanrılar ile kurban edilecek hayvan sayılarının listelendiği anıt hangisidir?', 'Meher Kapısı', ['Kral Kapısı', 'Sfenksli Kapı', 'Arslantepe Geçidi'], 'Tuşpa yakınlarındaki Meher Kapısı, kayadan tanrıların çıkacağına inanılan kutsal niş olup üzerinde Urartu dininin en kapsamlı kurban listesi yazılıdır.'),
  ('Hititlerde \'Tuhkanti\' unvanı saray hiyerarşisinde hangi görevliyi tanımlamak için kullanılmıştır?', 'Tahtın birinci sıradaki veliaht prensini', ['Sınır boylarındaki uç kalelerinin komutanını', 'Tapınak hazinelerini denetleyen başyazıcıyı', 'Yabancı elçileri karşılayan saray tercümanını'], 'Hitit yönetim protokolünde kraldan hemen sonra gelen meşru veliaht prense \'Tuhkanti\' denilmekteydi.'),
  ('Urartu Kralı I. Argişti\'nin Aras Nehri boylarında kurduğu ve bugünkü Erivan kentinin adının da kökenini oluşturan müstahkem Urartu kalesi hangisidir?', 'Erebuni', ['Hattuşa', 'Kركamış', 'Gordion'], 'I. Argişti tarafından MÖ 782 yılında inşa edilen Erebuni Kalesi, Urartuların kuzeydoğu yayılımındaki en önemli yönetim üslerinden biridir.'),
  ('Urartu dini mimarisinde \'Susi\' olarak adlandırılan kare planlı, kalın köşe kuleli ve tek hücreli yüksek taş yapıların temel işlevi nedir?', 'Kule tipi tapınak olarak kutsal törenlere ev sahipliği yapmak', ['Sınır geçitlerinde gümrük vergisi toplanan karakol olmak', 'Kraliyet atlarının kış aylarında barındırıldığı ahır olmak', 'Su kanallarının basıncını düşüren dinlendirme havuzu olmak'], 'Urartu kalelerinin en yüksek noktasına inşa edilen kare planlı, yüksek cepheli kule tapınaklara yazıtlarda \'Susi\' adı verilmektedir.'),
  ('Hitit Kralı I. Murşili\'nin Suriye\'yi aşıp Mezopotamya\'nın içlerindeki Babil\'i yağmalamasına rağmen bu kenti doğrudan Hitit topraklarına katmayıp geri dönmesinin en makul stratejik açıklaması nedir?', 'Merkez Hattuşa\'ya çok uzak olan bir bölgeyi kalıcı olarak elde tutmanın lojistik güçlüğü', ['Babil halkıyla aynı dili konuşan akraba topluluklara zarar vermek istememesi', 'Mısır donanmasının Karadeniz kıyılarına çıkarma yaptığı haberini alması', 'Pankuş meclisinin Fırat Nehri\'nin doğusunda toprak fethetmeyi dinen yasaklaması'], 'Babil, Orta Anadolu\'daki başkent Hattuşa\'dan çok uzakta olduğundan I. Murşili ganimet ve prestij elde ettikten sonra geri dönmüş, ancak yokluğunda saray entrikaları artmıştır.'),
  ('Urartu yazılı belgelerinde geçen ve kralın yanında eyaletleri yöneten \'EN.NAM\' unvanlı görevlilerin idari konumu aşağıdakilerden hangisine karşılık gelir?', 'Merkezden atanan askeri ve sivil yetkili eyalet valisi', ['Yalnızca kurban törenlerinde kehanette bulunan tapınak kâhini', 'Kervan yollarının güvenliğini sağlayan ücretli göçebe reisi', 'Maden ocaklarındaki cevheri işleyen lonca ustabaşısı'], 'Urartu Krallığı büyüdükçe ülke eyaletlere bölünmüş ve başlarına krala bağlı, askeri güce sahip valiler (EN.NAM) atanmıştır.'),
  ('Van Gölü kıyısındaki Ayanis Kalesi\'nde yürütülen kazılarda kule tapınağın iç duvarlarında kakma tekniğiyle yapılmış aslan, grifon ve hayat ağacı bezemeleri hangi Urartu kralının sanatsal hamiliğini yansıtır?', 'II. Rusa', ['İşpuini', 'Lutipri', 'Arame'], 'MÖ 7. yüzyılda II. Rusa tarafından kurulan Ayanis (Rusahinili Eiduru-kai), taş oyma ve kakma bezemeli Haldi tapınağıyla Urartu sanatının zirvesidir.'),
  ('Hitit İmparatorluğu\'nun son kralı II. Şuppiluliuma döneminde Kıbrıs (Alaşıya) açıklarında gerçekleşen askeri çarpışmanın dünya askeri tarihindeki önemi nedir?', 'Yazılı belgelerle kaydedilmiş en eski deniz savaşlarından biri olması', ['Barutlu topların gemi güvertelerinde ilk kez kullanılması', 'Demir zırhlı denizaltı benzeri dalgıç araçlarının denenmesi', 'Üç kıtadan gelen müttefik donanmaların okyanusta karşılaşması'], 'II. Şuppiluliuma\'nın Kıbrıs (Alaşıya) yakınlarında düşman gemilerini yenip yaktığını anlatan Boğazköy tableti, tarihin ilk kayıtlı deniz muharebelerindendir.'),
  ('Yozgat\'ın Sorgun ilçesindeki Kerkenes Dağı\'ndan önce Hitit dünyasında \'Kuşşara\' kentinden çıkarak Kaniş\'i ele geçiren ve Anadolu\'da kendi adını taşıyan en eski Türkçe dışı Hint-Avrupa metnini bırakan kral kimdir?', 'Anitta', ['Midas', 'Kroisos', 'Gyges'], 'Kuşşara Kralı Pithana\'nın oğlu Anitta, Kaniş\'i başkent yapmış ve Hitit dilinde bilinen en eski metin olan \'Anitta Metni\'ni yazdırmıştır.'),
  ('Hititlerin Çukurova ve çevresini kapsayan, Hurri ve Luvi kültürlerinin kaynaştığı ve Kraliçe Puduhepa\'nın da memleketi olan güney bölgesine verdikleri coğrafi ad nedir?', 'Kizzuvatna', ['Paflagonya', 'Bitinya', 'Kapadokya'], 'Antik Çağ\'da Kilikya (Çukurova) olarak bilinen bölge, Hitit metinlerinde dini ritüelleriyle ünlü \'Kizzuvatna\' ülkesi olarak geçer.'),
  ('Van Kalesi\'nin batı ucunda doğrudan göl kıyısına uzanan ve Urartu Krallığı\'nın kurucusu I. Sarduri tarafından Asur çivi yazısı ve diliyle yazdırılan anıtsal yapı hangisidir?', 'Madır Burcu', ['Kız Kulesi', 'Yedikule Zindanı', 'Hoşap Kümbeti'], 'I. Sarduri\'nin Tuşpa Kalesi\'nin batı ucuna dev kalker bloklarla inşa ettirdiği Madır (Sardur) Burcu, bilinen en eski Urartu yazıtlarını taşır.'),
  ('Hitit İmparatorluğu\'nda III. Hattuşili\'nin yeğeni Urhi-Teşup\'u tahttan indirerek iktidarı ele geçirdikten sonra kaleme aldırdığı \'Hattuşili\'nin Özürnamesi (Apologya)\' adlı metnin siyasi işlevi nedir?', 'Tahtı gasp etmesini Tanrıça İştar\'ın ilahi iradesine bağlayarak iktidarını meşrulaştırmak', ['Mısır Firavunu II. Ramses\'ten Kadeş Savaşı\'ndaki kayıplar için af dilemek', 'Ülkedeki kıtlık nedeniyle vergi oranlarını yarıya indirdiğini halka duyurmak', 'Pankuş meclisini süresiz olarak feshettiğini komşu krallıklara bildirmek'], 'III. Hattuşili Telepinuş yasasına aykırı biçimde yeğenini devirdiği için, bu darbesini Tanrıça İştar\'ın seçimi olarak sunan meşrulaştırıcı bir otobiyografi yazdırmıştır.'),
  ('Urartu Kralı İşpuini ile oğlu Menua\'nın ortak krallık döneminde dikilen ve bugünkü İran-Irak sınırındaki geçitte bulunan çift dilli (Urartuca-Asurca) anıt hangisidir?', 'Kelişin Steli', ['Karatepe Yazıtı', 'İvriz Kabartması', 'Kadeş Tableti'], 'Musasir tapınağına giden kutsal geçit üzerine dikilen Kelişin Steli, Urartuların Asurca yanında kendi dilleri Urartucayı anıtlarda kullanmaya başladığı önemli belgedir.'),
  ('MÖ 714 yılında Asur Kralı II. Sargon\'un \'Sekizinci Seferi\' sırasında yağmalanan ve Haldi\'nin ulusal tapınağının bulunduğu kutsal Urartu müttefik kenti neresidir?', 'Musasir', ['Gordion', 'Sardes', 'Miletos'], 'II. Sargon\'un Musasir Tapınağı\'nı yağmalaması hem tonlarca altın-tunç hazinenin kaybına hem de Kral I. Rusa\'nın derin sarsıntı yaşamasına neden olmuştur.'),
  ('Hitit saray arşivlerinde bulunan \'Kikkuli Metni\', antik çağ bilimi ve askeri teknolojisi açısından hangi uzmanlık alanına ait ayrıntılı bir el kitabıdır?', 'Savaş arabası atlarının yedi aylık beslenme ve antrenman programı', ['Demir cevherinin yüksek fırınlarda çelikleştirilme dereceleri', 'Bitkisel ilaçlarla açık savaş yaralarının dikilme yöntemleri', 'Yıldız tutulmalarına göre tarımsal ekim günlerinin hesaplanması'], 'Mitannili at eğitmeni Kikkuli tarafından kaleme alınan dört tabletlik metin, savaş atlarının kondisyon ve bakımını anlatan dünyanın en eski hipoloji belgesidir.'),
  ('Hitit Kralı I. Şuppiluliuma\'ya Mısır Kraliçesi (Dahamunzu) tarafından gönderilen mektupta kocasının öldüğünü ve ülkesinde oğlu olmadığını belirterek bir Hitit prensiyle evlenmek istemesi nasıl sonuçlanmıştır?', 'Mısır\'a gönderilen Prens Zannanza\'nın yolda öldürülmesiyle iki devlet arasında savaş çıkmıştır', ['İki imparatorluk tek bir hanedan çatısı altında birleşerek Babil\'i fethetmiştir', 'Pankuş meclisi yabancı bir kraliçeyle evliliği reddederek elçiyi hapsetmiştir', 'Hitit prensi Mısır firavunu olarak tahta çıkıp başkenti Hattuşa\'ya taşımıştır'], 'Şuppiluliuma araştırmalar sonunda oğlu Zannanza\'yı Mısır\'a göndermiş, ancak prensin yolda suikasta uğraması Hitit-Mısır düşmanlığını ve Suriye seferlerini başlatmıştır.'),
  ('Hitit taş işçiliğinde tapınak ve saray duvarlarının alt sıralarını kaplayan, ön yüzleri kabartmalarla süslenmiş dikey taş levhalara arkeoloji terminolojisinde ne ad verilir?', 'Ortostat', ['Akroter', 'Arşitrav', 'Karyatid'], 'Hitit ve Geç Hitit mimarisinde kerpiç üst yapıyı nemden koruyan ve kabartmalarla bezenen duvar eteği taş bloklarına \'ortostat\' denir.'),
  ('Hititlerde sınır bölgelerini dış saldırılara karşı korumakla görevlendirilen ve geniş askeri-yargısal yetkilere sahip uç beylerine hangi unvan verilmiştir?', 'Bel Madgalti', ['Tavananna', 'Karum Reisi', 'Şatammu'], 'Hitit sınır eyaletlerini yöneten, kalelerin onarımından, gözcülerden ve yerel davalardan sorumlu uç beylerine \'Bel Madgalti\' (Gözetleme Kulesi Beyi) denilirdi.'),
  ('Boğazköy\'de bulunan ve Hititlerin kendi köken efsanelerini anlattıkları \'Zalpa Metni\'nde Kaniş Kraliçesi\'nin otuz oğlunu sepetlerle bıraktığı nehrin denize döküldüğü yer neresidir?', 'Karadeniz kıyısındaki Zalpa kenti', ['Basra Körfezi\'ndeki Ur limanı', 'Akdeniz\'deki İskenderiye deltası', 'Ege kıyısındaki Efes körfezi'], 'Zalpa Efsanesi\'ne göre Kaniş Kraliçesi\'nin Kızılırmak\'a bıraktığı sepetler ırmağın Karadeniz\'e döküldüğü yerdeki Zalpa kentine ulaşmıştır.'),
  ('Hititlerde kral öldüğünde on dört gün süren \'Şallis Vaştaiş\' (Büyük Günah/Felaket) adlı cenaze töreninde cesedin yakıldıktan sonra kemiklerinin nereye konulması gelenekti?', 'Taş Ev (E.NA4) adı verilen anıt mezar tapınağına', ['Kızılırmak\'ın en derin kanyon sularına', 'Sfenksli Kapı\'nın altındaki gizli dehlize', 'Yalnızca Kültepe\'deki tüccar mezarlığına'], 'Hitit krallarının cesedi yakılır, toplanan kemikler yağ ve ketenle sarılarak \'Taş Ev\' (E.NA4) adı verilen kraliyet mozole/tapınağına yerleştirilirdi.'),
  ('Urartu toplumunda saray ve kalelerde bulunan mühürlerin hem alt yüzünde damga hem de yan yüzeyinde yuvarlanarak basılan silindir özelliğini bir arada taşıması hangi adla tanımlanır?', 'Damga-silindir mühür', ['Skarabe yüzük mühür', 'Bulla kurşun mühür', 'Tuğra ferman mühür'], 'Anadolu\'nun damga mühür geleneği ile Mezopotamya\'nın silindir mühür geleneğini birleştiren \'damga-silindir mühürler\' Urartu bürokrasisinin karakteristik üslubudur.'),
  ('Ankara\'nın Haymana ilçesi yakınlarında yer alan, kiklopik taş duvarlı terası ve tanrıların geçit sahnesiyle ünlü Hitit İmparatorluk dönemi kutsal alanı ve mezar odası hangisidir?', 'Gavurkalesi', ['Toprakkale', 'Patara', 'Labraunda'], 'Ankara Haymana\'daki Gavurkalesi, kaya yüzeyine işlenmiş anıtsal Hitit tanrı kabartmaları ve arkasındaki taş örme mezar odasıyla önemli bir kült merkezidir.'),
  ('Hitit Devleti\'nin yıkılış sürecinde yalnız dış istilaların değil, iç ekonomik krizin de etkili olduğunu gösteren Mısır Firavunu Merneptah\'ın yazıtındaki bilgi aşağıdakilerden hangisidir?', 'Hatti ülkesini yaşatmak için gemilerle Anadolu\'ya acil tahıl yardımı gönderilmesi', ['Hitit altın madenlerinin borç karşılığında Mısır tapınaklarına devredilmesi', 'Hattuşa halkının tamamının Nil Vadisi\'ne tarım işçisi olarak göç etmesi', 'Mısır sikkelerinin Anadolu pazarlarında tek geçerli para ilan edilmesi'], 'Firavun Merneptah\'ın Karnak yazıtında \'Hatti ülkesini hayatta tutmak için gemilerle tahıl gönderdim\' ifadesi, MÖ 13. yüzyıl sonundaki şiddetli kuraklık ve kıtlığı kanıtlar.'),
  ('Urartu panteonunda baş tanrı Haldi ve Fırtına Tanrısı Teişeba ile birlikte ilk üçlü (triad) grubu tamamlayan Güneş Tanrısı aşağıdakilerden hangisidir?', 'Şivini', ['Apollon', 'Ra', 'Enlil'], 'Urartu devlet dininin en üst üçlüsünü Savaş Tanrısı Haldi, Fırtına Tanrısı Teişeba ve kanatlı güneş kursuyla simgelenen Güneş Tanrısı Şivini oluşturur.'),
  ('Hitit arşivlerinde kadın falcıların, şifacıların ve büyü ritüellerini yöneten uzman kadınların (\'Yaşlı Kadın\' / MUNUS ŞU.GI) sıkça geçmesi Hitit toplumu hakkında neyi ortaya koyar?', 'Arınma ve şifa ritüellerinde kadın din görevlilerinin kurumsal bir uzmanlığa sahip olduğunu', ['Erkeklerin tapınaklara girmesinin kanunen tamamen yasaklandığını', 'Tıp biliminin yalnızca yabancı Mısırlı kölelere bırakıldığını', 'Büyü yapan tüm kadınların sorgusuzca sürgün cezasına çarptırıldığını'], 'Hitit tabletlerinde kara büyüyü bozma, arındırma ve şifa ritüellerini yürüten \'Yaşlı Kadınlar\' (MUNUS ŞU.GI) saygın ve resmi ritüel uzmanları olarak kayıtlıdır.'),
  ('Lidya Kralı Kroisos (Karun) döneminde elektron sikkelerin içindeki altın ve gümüş oranının doğal olarak değişmesinden kaynaklanan ticari güvensizlik hangi yenilikle çözülmüştür?', 'Altın ve gümüşün rafine edilip ayrıştırılarak saf altın ve saf gümüş sikkelerin ayrı ayrı basılmasıyla', ['Madenî paranın tamamen yasaklanıp yeniden arpa ve buğdayla takas usulüne dönülmesiyle', 'Sikkelerin üzerine kral mührü yerine yalnızca yabancı tüccarların imzasının vurulmasıyla', 'Paraların değerinin ağırlığına göre değil, basıldığı tapınağın uzaklığına göre belirlenmesiyle'], 'Sardes\'teki altın arıtma (sementasyon) atölyelerinde altın ve gümüşü ayrıştıran Kroisos, tarihin ilk çift madenli (bimetalik) saf altın ve gümüş sikke sistemini kurmuştur.'),
  ('Karya bölgesinin Milas yakınlarındaki dağlık kutsal alanı Labraunda\'da tapınılan Zeus Stratios\'un elinde tuttuğu ve Karyalıların ulusal simgesi sayılan çift ağızlı baltaya ne ad verilir?', 'Labrys', ['Gladius', 'Fasces', 'Trident'], 'Anadolu ve Ege kültüründe kutsal güç simgesi olan çift ağızlı balta \'labrys\', Karya\'daki Zeus Labraundos kültünün başlıca sembolüdür.'),
  ('On iki İyon şehir devletinin (Dodekapolis) temsilcilerinin Dilek Yarımadası\'nın (Mykale) kuzey eteklerinde ortak dini şenlikler düzenlemek ve siyasi konuları görüşmek üzere toplandıkları kutsal merkez neresidir?', 'Panionion', ['Olimpia', 'Delfi', 'Akropolis'], 'Aydın Kuşadası Güzelçamlı\'daki Panionion, Poseidon Helikonios tapınağı çevresinde 12 İyon polisinin dinsel ve kültürel birlik merkeziydi.'),
  ('Gordion kazılarında MÖ 9.-8. yüzyıl megaron tabanlarında bulunan renkli dere çakıllarının yan yana dizilmesiyle oluşturulmuş geometrik zemin kaplamalarının sanat tarihindeki yeri nedir?', 'Bilinen en erken çakıl taşı mozaik döşeme örnekleri olmaları', ['Sırlı çini sanatının Anadolu\'daki ilk duvar kaplamaları olmaları', 'Cam prizmalarla yapılan vitray tekniğinin öncüsü sayılmaları', 'Mermer kakma opus sectile tarzının Roma dönemi kopyaları olmaları'], 'Gordion\'daki Megaron 2\'de ortaya çıkarılan koyu kırmızı, beyaz ve mavimsi çakıl taşlarıyla döşenmiş geometrik zemin, dünyanın en eski çakıl mozaiklerinden biridir.'),
  ('MÖ 480 yılındaki Salamis Deniz Savaşı\'nda Pers Kralı Kserkses\'in donanmasında bizzat filo komutanı olarak savaşan ve stratejik zekâsıyla antik tarihçilerin övgüsünü kazanan Karya kraliçesi kimdir?', 'I. Artemisia', ['Puduhepa', 'Kleopatra', 'Zenobia'], 'Halikarnas hükümdarı olan Karya Kraliçesi I. Artemisia, Pers donanmasındaki tek kadın amiral olarak Salamis Savaşı\'nda gösterdiği cesaret ve taktik öngörüyle Herodot Tarihi\'ne geçmiştir.'),
  ('Aydın Söke yakınlarında Büyük Menderes Ovası\'na hâkim bir yamaçta MÖ 4. yüzyılda yeniden kurulan ve Miletli Hippodamos\'un geliştirdiği birbirini dik kesen cadde-sokak (ızgara) planının en kusursuz örneği sayılan İyon kenti hangisidir?', 'Priene', ['Hattuşa', 'Tuşpa', 'Kaniş'], 'Samsun Dağı yamacındaki Priene antik kenti, teraslar üzerine oturtulmuş ızgara (Hippodamos) kent planlamasının Anadolu\'daki en iyi korunmuş örneğidir.'),
  ('Datça Yarımadası\'nın ucunda çift limanlı bir Karya/Dor kenti olarak yükselen, ünlü matematikçi-astronom Eudoksos\'un gözlemevine ve Praksiteles\'in Afrodit heykeline ev sahipliği yapan merkez hangisidir?', 'Knidos', ['Patara', 'Side', 'Pergamon'], 'Ege ve Akdeniz\'in birleştiği noktadaki Knidos; tıp okulu, Eudoksos\'un güneş saati ve antik çağın en ünlü çıplak Afrodit heykeliyle bilim ve sanat merkezidir.'),
  ('Lidya Krallığı\'nda Mermnad Hanedanı\'nı kuran Kral Gyges\'in Asur Kralı Asurbanipal\'e elçiler göndererek ittifak aramasının temel güvenlik gerekçesi nedir?', 'Frigya\'yı yıktıktan sonra Batı Anadolu\'yu ve Sardes\'i tehdit eden Kimmer akınlarını durdurmak', ['Mısır donanmasının Ege adalarını işgal etmesini engellemek', 'Urartu ordularıyla birlikte Babil kentini yağmalamak', 'İyon şehirlerinin Karadeniz\'de koloni kurmasını yasaklamak'], 'Kimmerler Gordion\'dan sonra Lidya\'ya yönelince Kral Gyges, Asur Kralı Asurbanipal\'den yardım istemiş; ancak sonraki Kimmer saldırısında Gyges savaş meydanında ölmüştür.'),
  ('Milet Okulu filozoflarından Anaksimandros\'un bilim tarihine kazandırdığı somut çalışmalardan biri aşağıdakilerden hangisidir?', 'Güneş saati (gnomon) kullanımı ve bilinen ilk dünya haritası çizimi', ['Barutun itici gücüne dayanan ok fırlatma mekanizması', 'Matbaa harflerinin kurşun kalıplarla çoğaltılması', 'Su gücüyle çalışan otomatik çalar saat düzeneği'], 'Thales\'in öğrencisi Miletli Anaksimandros, ilk kez bilinen dünyanın coğrafi haritasını çizmiş, güneş saatini tanıtmış ve evrenin ana ilkesini \'apeiron\' (sınırsız) olarak açıklamıştır.'),
  ('Frig mimarisinde çatı kiremitlerinin ve ahşap saçakların yağmur ve nemden çürümesini önlemek amacıyla cepheye çakılan kabartmalı ve renkli pişmiş toprak levhalara ne ad verilir?', 'Mimari kaplama levhası', ['Bazalt ortostat bloğu', 'Sırlı çini mukarnas', 'Fildişi kakma pano'], 'Pazarlı ve Gordion kazılarında bulunan yürüyen askerler, grifonlar ve keçi figürlü renkli pişmiş toprak kaplama levhaları Frig ahşap çatılarını koruyup süslemiştir.'),
  ('Muğla Yatağan\'da bulunan, antik çağda gladyatör okulu ve mermer sütunlu caddeleriyle ün kazanan, dünyanın en büyük mermer antik kentlerinden biri kabul edilen Karya yerleşimi hangisidir?', 'Stratonikeia', ['Alacahöyük', 'Çavuştepe', 'Kültepe'], 'Karya\'nın iç kesimindeki Stratonikeia, Hekate kutsal alanı bağlantısı, dev gymnasionu ve gladyatör mezar taşlarıyla ünlü mermer kenttir.'),
  ('Likyalıların kendilerini Yunanca \'Lykioi\' adıyla değil, kendi yerli Luvi kökenli dillerindeki yazıtlarda hangi isimle adlandırdıkları tespit edilmiştir?', 'Trmmili', ['Hattili', 'Muşkili', 'Pelasg'], 'Ksantos Dikilitaşı ve Letoon üç dilli yazıtında görüldüğü üzere Likyalılar kendi dillerinde ülkelerine \'Trmmisa\', halkına ise \'Trmmili\' demişlerdir.'),
  ('Fethiye yakınlarındaki Letoon Kutsal Alanı\'nda bulunan ve Likçe, Grekçe ile Aramice olarak üç dilde yazılmış olan stel hangi açıdan dilbilim tarihinde çığır açmıştır?', 'Anadolu\'nun yerli dillerinden Likçenin gramer yapısının ve sözcüklerinin çözülmesini sağlaması', ['Sümer çivi yazısının hangi tarihte icat edildiğini gün ve ay olarak bildirmesi', 'Lidya sikkelerinin sahtesini ayırt etmek için kullanılan kimyasal formülü içermesi', 'Hitit Kralı Hattuşili\'nin vasiyetnamesinin kayıp son sayfasını barındırması'], '1973\'te Letoon kazılarında bulunan MÖ 4. yüzyıla ait üç dilli (Likçe-Grekçe-Aramice) yazıt, Hint-Avrupa Anadolu dil ailesinden Likçenin anlaşılmasında anahtar olmuştur.'),
  ('İzmir\'in Seferihisar ilçesindeki Teos antik kentinde yer alan Dionysos Tapınağı ve burada üslenmiş olan \'Dionysos Sanatçıları Birliği\' İyonya kültür hayatının hangi yönünü temsil eder?', 'Tiyatro oyuncuları, şairler ve müzisyenlerin mesleki lonca halinde örgütlendiği sahne sanatlarını', ['Savaş gemisi yapan marangozların askeri sırları koruduğu tersane teşkilatını', 'Yalnızca mermer heykeltıraşlarının kabul edildiği kapalı saray atölyesini', 'Zeytinyağı tüccarlarının deniz sigortası poliçesi düzenlediği borsa meclisini'], 'İyon kenti Teos, MÖ 3. yüzyılda tiyatro aktörleri, müzisyenler ve ozanların ilk kurumsal meslek örgütü olan Dionysos Sanatçıları Birliği\'nin merkezi olmuştur.'),
  ('İzmir\'in Urla ilçesindeki Klazomenai antik kentinde yapılan kazılarda MÖ 6. yüzyıla tarihlenen kaya oygu tekneler, pres ağırlıkları ve dinlendirme havuzları hangi sanayi kolunun en erken tesisini belgelemiştir?', 'Büyük ölçekli zeytinyağı üretim işliği', ['Deniz kabuklarından mor boya çıkarma fabrikası', 'Kuvars kumundan pencere camı döküm fırını', 'Pamuk kozasından yelken bezi dokuma tezgâhı'], 'Klazomenai\'de ortaya çıkarılan MÖ 6. yüzyıl zeytinyağı işliği, Anadolu\'da zeytinyağının ticari ölçekte seri üretildiğini ve amforalarla ihraç edildiğini kanıtlayan en eski tesistir.'),
  ('Frig çanak çömlek sanatında bir yanda tek renkli (gri-siyah cilalı) kaplar üretilirken diğer yanda Kızılırmak doğusunda çok renkli, dama tahtası ve stilize geyik-kuş bezemeli kapların yapılması neyi gösterir?', 'Batı ve Orta Anadolu yerli çömlekçilik geleneklerinin Frig üslubu içinde bölgesel çeşitlilik kazandığını', ['Boyalı kapların tamamının Mısır\'dan ithal edilip yerli üretimin yasaklandığını', 'Siyah kapların yalnızca köleler, boyalı kapların ise sadece rahipler için üretildiğini', 'Friglerin seramik fırınlarında sır kullanmayı Çinlilerden öğrendiklerini'], 'Sakarya havzasındaki Gordion\'da monokrom (gri/siyah madeni görünümlü) kaplar ağırlıktayken, Kızılırmak kavsinde Alişar-Boğazköy hattında geometrik ve hayvan figürlü boyalı Frig seramiği gelişmiştir.'),
  ('Karya kentlerinin iç bölgelerde başlangıçta birbirine yakın tepe köylerinin ortak bir tapınak etrafında birleşmesiyle (\'koinon\' sistemi) örgütlenip İskender ve Mausolos dönemlerinde kıyı odaklı polislere dönüşmesi hangi sürece örnektir?', 'Kırsal boy federasyonlarından Helenistik kentleşme (synoikismos) modeline geçişe', ['Yerleşik şehir yaşamının terk edilerek tamamen yaylak-kışlak göçebeliğine dönülmesine', 'Deniz ticaretinin bırakılıp yalnızca yer altı maden şehirlerinde yaşanmasına', 'Tapınak arazilerinin yabancı paralı askerler arasında kurayla paylaştırılmasına'], 'Mausolos, Karya\'daki dağınık yerli tepe yerleşimlerini Halikarnas gibi planlı kentlerde birleştirerek (synoikismos) Karya\'nın kentsel ve siyasi gücünü artırmıştır.'),
  ('Frig mobilya sanatının ulaştığı yüksek düzeyi kanıtlayan, Gordion Tümülüsü\'nden çıkarılmış şimşir, ardıç ve porsuk ağaçlarının kakma tekniğiyle birleştirildiği geometrik desenli eserler hangileridir?', 'Ahşap servis masaları ve paravanlar', ['Fildişi kaplamalı tahtırevanlar', 'Tunç tekerlekli cenaze arabaları', 'Altın varaklı tapınak kapıları'], 'Midas Tümülüsü\'nde bulunan ve üç farklı tondaki ağacın çivi kullanılmadan geçme-kakma tekniğiyle işlendiği masalar ve paravanlar antik ahşap işçiliğinin zirvesidir.'),
  ('Karya\'nın iç kesimindeki Afrodisias ve Lagina tapınaklarında görülen \'asylia\' (dokunulmazlık/sığınma hakkı) ayrıcalığı antik çağda ne tür bir işlev görmüştür?', 'Savaş dönemlerinde bile kutsal alana sığınanların can ve mal güvenliğinin korunmasını sağlamıştır', ['Tapınak rahiplerinin komşu şehirlerden zorla asker toplamasına izin vermiştir', 'Yabancı tüccarların sattıkları mallardan iki kat gümrük alınmasını getirmiştir', 'Yalnızca kral soyundan gelenlerin tapınak bahçesine girmesini kurala bağlamıştır'], 'Helenistik ve Roma dönemlerinde de onaylanan Anadolu tapınaklarındaki \'asylia\' hakkı, kutsal alanı yağmadan koruyan ve sığınmacılara dokunulmazlık sağlayan hukuki bir güvenceydi.'),
  ('Klazomenai (Urla) çömlek ustalarının MÖ 6. yüzyılda ürettikleri ve ağız kenarları siyah/kırmızı figürlü savaş arabaları, hayvan dizileri ve mitolojik sahnelerle boyanmış büyük pişmiş toprak tabutlara ne ad verilir?', 'Klazomenai lahitleri', ['Urartu urneleri', 'Frig tümülüsleri', 'Likya dikmeleri'], 'İyonya kenti Klazomenai\'ye özgü, pişmiş topraktan yapılıp geniş üst çerçeveleri vazo ressamlığı üslubunda boyanmış \'Klazomenai lahitleri\' dünya müzelerinin başyapıtları arasındadır.'),
  ('İzmir\'in Bergama ile Foça arasındaki Aiolis bölgesiyle komşu olan Smyrna (Bayraklı Höyüğü) kazılarında ortaya çıkarılan MÖ 7. yüzyıl Athena Tapınağı hangi yönüyle önem taşır?', 'Batı Anadolu\'da mantar (yaprak) başlıklı erken taş tapınak mimarisinin öncü örneklerinden olmasıyla', ['Tamamen dökme demir sütunlarla inşa edilmiş tek antik yapı olmasıyla', 'Hitit Kralı Şuppiluliuma tarafından deniz tanrısına adanmış olmasıyla', 'İçinde on binlerce çivi yazılı kil tablet arşivinin bulunmasıyla'], 'Eski İzmir (Bayraklı) ören yerindeki Athena Tapınağı, Doğu Yunan/Anadolu erken arkaik mimarisinin ve özgün yapraklı (Aiol/proto-İyon) başlık gelişiminin kilit yapısıdır.'),
  ('Milet Okulu\'nun üçüncü büyük temsilcisi Anaksimenes\'in evrenin ilk maddesini (arkhe) \'hava\' olarak belirleyip yoğunlaşma ve seyrekleşme süreçleriyle taş, su, bulut ve ateşin oluştuğunu savunması neden bilimsel bir adımdır?', 'Niteliksel farklılıkları maddenin fiziksel yoğunluk değişimi gibi doğal bir mekanizmayla açıklaması', ['Havanın kimyasal elementlerini oksijen ve azot olarak laboratuvarda ayrıştırması', 'Rüzgâr tanrılarının öfkesini yatıştırmak için yeni kurban törenleri önermesi', 'Gökyüzündeki gezegenlerin elips yörüngelerini teleskopla gözlemlemesi'], 'Anaksimenes mitolojik güçlere başvurmadan, tek bir maddenin seyrekleşme (ısınma) ve sıkışma (soğuma) gibi nicel değişimlerle farklı hallere geçtiğini öne sürerek doğa bilimine yaklaşmıştır.'),
  ('Likya kentlerindeki tiyatro, meclis binası (bouleuterion) ve hamam gibi görkemli yapıların çoğunun Opramoas gibi varlıklı yerel hayırseverlerin bağışlarıyla inşa edilmesi antik dünyada hangi kavramla ifade edilir?', 'Evergetizm (kent yararına kamusal hayırseverlik)', ['Ostrakismos (çanak çömlek oylamasıyla sürgün)', 'Feodalizm (toprağa bağlı serflik düzeni)', 'Merkantilizm (değerli maden korumacılığı)'], 'Özellikle Rhodiapolisli Opramoas\'ın tüm Likya kentlerine yaptığı büyük bağışlarla simgeleşen \'evergetizm\', zengin yurttaşların kamu yapılarını finanse ederek onurlandırılması geleneğidir.'),
  ('Karya bölgesinin yerli halkının Yunan ordularına ve Mısır firavunlarına bile ücretli asker olarak hizmet ederken miğferlerine horoz tüyleri takmaları ve kalkanlarına tutamak ile arma eklemeleri hangi alandaki ustalıklarını gösterir?', 'Piyade silah donanımına yenilikler kazandıran savaşçı bir topluluk olmalarını', ['Savaşmaktan kaçınarak yalnızca tören muhafızlığı yaptıklarını', 'Zırh yapımında metal yerine sadece ahşap malzeme kullandıklarını', 'Okçuluk dışında hiçbir yakın dövüş silahını tanımadıklarını'], 'Herodot\'a göre Karyalılar miğfere sorguç takma, kalkana kol bağı/tutamak yapma ve kalkan yüzeyine arma işleme yeniliklerini Ege dünyasına tanıtan usta savaşçılardı.'),
  ('Miletli bilgin Hekataios\'un MÖ 6. yüzyıl sonunda yaptığı seyahatlere dayanarak kaleme aldığı \'Yeryüzünün Tasviri (Periodos Ges)\' adlı eser hangi bilim dalının kuruluşunda dönüm noktasıdır?', 'Beşeri ve fiziki coğrafya ile etnografya', ['Cerrahi anatomi ve eczacılık', 'Deneysel optik ve akustik', 'Maden ergitme kimyası'], 'Miletli Hekataios, Anaksimandros\'un haritasını geliştirip Akdeniz ve Karadeniz kıyı halklarını, kentlerini ve mesafelerini betimleyerek bilimsel coğrafyanın öncüsü olmuştur.'),
  ('Karya bölgesinin iç kesimindeki Yatağan Lagina\'da bulunan ve çatısındaki frizlerde Amazonlarla Yunanlıların dostça el sıkışmasını da betimleyen ünlü tapınak hangi tanrıçaya adanmıştır?', 'Hekate', ['Demeter', 'Persephone', 'Nemesis'], 'Stratonikeia\'ya kutsal yolla bağlı olan Lagina Hekate Tapınağı, Anadolu\'da yol kavşaklarının ve ay/gece gizemlerinin tanrıçası Hekate\'ye adanmış en önemli merkezdir.'),
  ('Lidya dilinin Hint-Avrupa dil ailesinin Anadolu koluna mensup olduğunun kesinleşmesini sağlayan en önemli arkeolojik buluntu grubu aşağıdakilerden hangisidir?', 'Sardes kazılarında bulunan Lidce-Aramice ve Lidce-Grekçe çift dilli mezar yazıtları', ['Boğazköy arşivinden çıkan Lidya-Mısır barış antlaşması kil tabletleri', 'Gordion tümülüsündeki ahşap masaların altına kazınmış hiyeroglif mühürler', 'Van Kalesi kayalıklarına Pers şahları tarafından yazdırılan üç dilli kitabeler'], '20. yüzyıl başında Sardes\'te bulunan özellikle Lidce-Aramice çift dilli (bilingual) mezar stelleri sayesinde Lidya alfabesi ve dili çözülmüştür.'),
  ('MÖ 6. yüzyılda Pers istilası karşısında esareti kabul etmeyerek gemilerine binip tüm taşınır mallarıyla birlikte kentlerini terk ederek Batı Akdeniz\'deki kolonilerine göç eden İyon şehir halkları hangileridir?', 'Phokaia (Foça) ve Teos (Sığacık) halkları', ['Miletos ve Priene halkları', 'Sardes ve Gordion halkları', 'Ksantos ve Patara halkları'], 'Pers komutanı Harpagos kuşatması sırasında Foçalılar Korsika/Marsilya yönüne, Teoslular ise Trakya\'daki Abdera\'ya topluca göç ederek özgürlüklerini korumaya çalışmışlardır.'),
  ('1100 yılında Malatya yakınlarındaki çarpışmada Antakya Haçlı Kontu I. Bohemund\'u esir alarak Niksar Kalesi\'nde hapseden ve Haçlıların yenilmezliği algısını yıkan Danişmendli hükümdarı kimdir?', 'Danişmendli Gümüştekin Ahmet Gazi', ['Saltuklu Beyi İzzeddin Saltuk', 'Mengücekli Hükümdarı Behramşah', 'Ahlatşahlar Beyi Sökmen el-Kutbi'], 'I. Haçlı Seferi\'nin en güçlü liderlerinden Bohemund\'u Malatya pususunda esir alan Danişmend Gazi (Gümüştekin), fidye alana dek onu Niksar\'da tutmuştur.'),
  ('Mengücekli hükümdarı Fahreddin Behramşah adına ünlü şair Nizami-i Gencevî\'nin Farsça kaleme alıp sunduğu ve hükümdara beş bin altın ile ödüllendirildiği edebi şaheser hangisidir?', 'Mahzenü\'l-Esrar', ['Mantıku\'t-Tayr', 'Mesnevi-i Manevi', 'Hüsn ü Aşk'], '60 yılı aşkın süre Erzincan\'da adaletle hüküm süren Mengücekli Fahreddin Behramşah ilim ve edebiyat hamisiydi; Genceli Nizami ilk mesnevisi \'Mahzenü\'l-Esrar\'ı ona ithaf etmiştir.'),
  ('İlk Türk beyliklerinden Danişmendlilerin kestirdikleri bakır sikkelerin bir yüzünde hükümdar unvanlarının Grekçe harflerle veya Hristiyan tebaanın aşina olduğu simgelerle basılmasının temel nedeni nedir?', 'Bölgedeki ticari tedavülü aksatmamak ve çok kültürlü yerli halkla ekonomik uyumu kolaylaştırmak', ['Danişmendli beylerinin İslamiyet\'i bırakarak Bizans Ortodoks kilisesine bağlanması', 'Arap alfabesini bilen hiçbir darphane ustasının Anadolu\'da bulunmaması', 'Haçlı devletlerine yıllık vergi öderken Bizans parası kullanma zorunluluğu'], 'Erken dönem Danişmendli, Saltuklu ve Artuklu bakır sikkelerinde bölgesel ticaret alışkanlıklarını korumak amacıyla Grekçe yazılar veya figürlü tasvirler pragmatik biçimde kullanılmıştır.'),
  ('Bitlis ve Erzen dolaylarında Malazgirt komutanlarından Dilmaçoğlu Mehmed Bey tarafından kurulan, Kurtulmuşoğlu Tekin\'in yaptığı Bitlis Ulu Camii gibi eserler bırakan birinci dönem Türk beyliği hangisidir?', 'Dilmaçoğulları', ['Batı Anadolu\'da denizcilik yapan Karesioğulları', 'Kütahya merkezli kurulan Germiyanoğulları', 'Maraş ve Elbistan\'a hâkim olan Dulkadiroğulları'], '1085\'te Bitlis ve Erzen çevresinde kurulan Dilmaçoğulları, Büyük Selçuklu ve Artuklu nüfuzu altında 14. yüzyıl sonlarına dek varlığını koruyan ilk dönem beyliklerindendir.'),
  ('1119 yılında Antakya Haçlı Prensliği ordusunu \'Ager Sanguinis\' (Kanlı Meydan / Tellü\'l-Afarîn) Savaşı\'nda ağır bir yenilgiye uğratarak Halep\'i Haçlı işgalinden kurtaran Mardin Artuklu hükümdarı kimdir?', 'Necmeddin İlgazi', ['Süleymanşah bin Kutalmış', 'Fahreddin Kara Arslan', 'Muinüddin Pervane'], 'Artuk Bey\'in oğlu ve Bağdat şahneliği de yapmış olan Mardin Artuklu Beyi Necmeddin İlgazi, 1119\'da Haçlı Kontu Roger\'in ordusunu imha ederek Kuzey Suriye\'yi korumuştur.'),
  ('Saltuklu hükümdarı II. İzzeddin Saltuk\'un 1153 dolaylarında Ani kuşatması sırasında Gürcü Kralı III. Giorgi\'ye esir düşmesi üzerine kurtuluş fidyesinin kimler tarafından ödenmesi dönemin dayanışmasını gösterir?', 'Artuklu, Ahlatşah ve diğer komşu Müslüman Türk hükümdarlarının aralarında yüz bin dinar toplaması', ['Bizans İmparatoru\'nun İstanbul hazinesinden karşılıksız altın göndermesi', 'Venedik tüccarlarının gümrük ayrıcalığı karşılığında borç senetleri vermesi', 'Haçlı tapınak şövalyelerinin esir takası yoluyla kefil olması'], 'Sökmenli Şah Banu Hatun ve Mardin Artuklu Hükümdarı Timurtaş başta olmak üzere Müslüman hükümdarların kendi aralarında 100.000 dinar fidye toplayarak İzzeddin Saltuk\'u kurtarması tarihi bir dayanışma örneğidir.'),
  ('Diyarbakır (Amid) kentinde 11. yüzyıl sonundan 1183\'te Selahaddin Eyyubi ve Artuklu hâkimiyetine girene dek hüküm süren, Ulu Cami\'nin onarımına ve Amida surlarına katkıda bulunan küçük Türk beyliği hangisidir?', 'İnaloğulları', ['Saruhanoğulları', 'Menteşeoğulları', 'Karamanoğulları'], 'Diyarbakır ve çevresinde Sadr Bey ve İnal Bey soyundan gelen İnaloğulları (ve vezirleri Nisanoğulları) birinci dönem Anadolu Türk beylikleri arasında yer almıştır.'),
  ('Elazığ (Harput) ve Palu çevresinde Sultan Melikşah\'ın komutanlarından Çubuk Bey tarafından 1085 yılında kurulan ve bir süre sonra yerini Harput Artuklularına bırakan beylik hangisidir?', 'Çubukoğulları', ['Eşrefoğulları', 'Hamitoğulları', 'Pervaneoğulları'], 'Diyarbakır\'ın fethinde Artuklular ve Büyük Selçuklu ordusunda görev alan Çubuk Bey\'in Harput merkezli kurduğu Çubukoğulları, 1112\'de Belek Gazi tarafından Artuklu topraklarına katılmıştır.'),
  ('Artuklu emirlerinden Belek Gazi\'nin (Nurüddevle Belek) Haçlı tarihçilerince bile korku ve saygıyla anılmasını sağlayan 1122-1123 yıllarındaki en çarpıcı askeri başarısı nedir?', 'Urfa Kontu Joscelin ile Kudüs Kralı II. Baudouin\'i esir alarak Harput Kalesi\'ne hapsetmesi', ['Rodos Adası\'ndaki şövalye kalesini denizden kuşatarak teslim alması', 'Venedik donanmasını İskenderun Körfezi\'nde top ateşiyle batırması', 'Konstantinopolis surlarını aşarak Ayasofya\'da kendi adına hutbe okutması'], 'Artuklu kahramanı Belek Gazi, önce Urfa Kontu Joscelin\'i, ardından onu kurtarmaya gelen Kudüs Kralı II. Baudouin\'i esir alıp Harput Kalesi\'ne kapatarak Haçlı dünyasını sarsmıştır.'),
  ('El-Cezerî\'nin Diyarbakır İçkale\'deki Artuklu Sarayı\'na nehir suyunu çıkarmak için geliştirdiği çift etkili emme-basma tulumba düzeneğinde kullandığı hangi mekanik parça modern motorların atası sayılır?', 'Dairesel hareketi doğrusal harekete çeviren krank mili ve biyel kolu mekanizması', ['Kömür buharıyla dönen çok kanatlı çelik türbin pervanesi', 'Mıknatıs kutuplarıyla elektrik üreten bakır bobin sargısı', 'Sıvı yakıtı sıkıştırarak ateşleyen buji ateşleme odası'], 'El-Cezerî su kaldırma makinelerinde su çarkının dönme hareketini pistonun ileri-geri doğrusal hareketine dönüştüren krank mili (krank-biyel) sistemini Avrupa\'dan yüzyıllar önce kullanmıştır.'),
  ('Erzurum Ulu Camii\'nin (Atabey Camii) 1179 yılında Saltuklu hükümdarı Nasreddin Muhammed tarafından inşa ettirilirken çok ayaklı (ulu cami) plan şeması ve mihrap önü kırlangıç kubbesiyle yapılması hangi geleneğin izini taşır?', 'Orta Asya-Kafkasya ahşap bindirme tavan (kırlangıç örtü) geleneğinin taş mimariye uyarlanmasının', ['Gotik katedrallerdeki yüksek uçan payanda ve gül pencere üslubunun kopyalanmasının', 'Mısır piramitlerindeki dar mezar koridorlarının ibadet mekânına dönüştürülmesinin', 'İyon tapınaklarındaki volütlü açık revak planının aynen tekrar edilmesinin'], 'Erzurum Ulu Camii\'nin mihrap önündeki \'kırlangıç kubbe\' (bindirme tekniği), Türklerin geleneksel ahşap çadır/konut örtü sisteminin kesme taşa aktarılmış özgün bir örneğidir.'),
  ('11. yüzyıl sonlarında Efes (Ayasuluk) ve çevresini kısa süreliğine ele geçirerek Batı Anadolu kıyılarında Türk varlığını hissettiren Türkmen beyi aşağıdakilerden hangisidir?', 'Tanrıvermiş Bey', ['Sökmen el-Kutbi', 'Nizameddin Yağıbasan', 'Hüsameddin Timurtaş'], '1071 sonrası Batı Anadolu\'ya uzanan akınlarda Efes ve çevresinde Tanrıvermiş Bey beylik kurmuş, ancak I. Haçlı Seferi sonrasında Bizans bölgeyi geri almıştır.'),
  ('Diyarbakır Silvan\'da (Meyyafarikin) Artuklu hükümdarı Necmeddin Alpi döneminde 1152-1157 yıllarında tamamlanan Silvan Ulu Camii\'nin İslam mimarisi tarihindeki önemi nedir?', 'Büyük Selçuklu camilerindeki geniş mihrap önü kubbesi geleneğini Anadolu taş mimarisine anıtsal ölçekte taşıması', ['Anadolu\'da minaresi olmayan tek yer altı ibadethanesi olarak inşa edilmesi', 'Tamamen pişmiş tuğladan yapılıp hiçbir kesme taş kullanılmaması', 'Kubbesinin kurşun yerine saf altın levhalarla kaplanmış olması'], '13,5 metre çapındaki görkemli mihrap önü kubbesiyle Silvan Ulu Camii, İran Büyük Selçuklu cami şemasının Güneydoğu Anadolu kesme taş işçiliğindeki en olgun sentezidir.'),
  ('Mardin Artuklu Beyliği\'nin 1409 yılında hangi devlet tarafından ortadan kaldırılmasıyla Anadolu\'da Malazgirt sonrası kurulan birinci dönem Türk beyliklerinden en uzun ömürlü olanının siyasi varlığı sona ermiştir?', 'Karakoyunlular', ['Büyük Selçuklular', 'Eyyubiler', 'Tolunoğulları'], 'Hasankeyf koluna 1232\'de Eyyubiler, Harput koluna 1234\'te Türkiye Selçukluları son verirken; Mardin Artukluları 1409\'da Karakoyunlu Kara Yusuf dönemine dek üç yüzyılı aşkın yaşamıştır.'),
  ('Van Gölü\'nün kuzeybatısındaki Ahlat\'ı başkent yapan Sökmenlilerin (Ahlatşahlar), \'Şah-ı Ermen\' unvanını kullanmaları aşağıdakilerden hangisiyle açıklanır?', 'Hükmettikleri bölgenin eski İslam coğrafya kaynaklarındaki \'Ermeniye\' vilayeti adından dolayı coğrafi bir unvan almalarıyla', ['Hükümdar ailesinin Türk olmayıp Ermeni Bagratuni hanedanından gelmesiyle', 'Devletin resmi dininin Hristiyanlık olarak kabul edilmiş bulunmasıyla', 'Gürcü kralları tarafından kendilerine vassallık nişanı verilmesiyle'], 'Tıpkı Türkiye Selçuklu sultanlarının Roma diyarı anlamında \'Sultanü\'r-Rum\' unvanını kullanması gibi, Türkmen Sökmen Bey ve halefleri de bölgenin tarihi coğrafi adıyla \'Şah-ı Ermen\' olarak anılmıştır.'),
  ('Mengücekli sarayında ve Divriği Darüşşifası çevresinde bir dönem bulunarak Anadolu\'nun coğrafyası, bitki örtüsü ve tıp bilimi üzerine gözlemler yapan ünlü Bağdatlı hekim ve filozof kimdir?', 'Muvaffaküddin Abdüllatif el-Bağdadi', ['Endülüslü seyyah İbn Battuta', 'Harzemli astronom El-Biruni', 'Tunuslu tarihçi İbn Haldun'], '13. yüzyıl başlarında Erzincan ve Divriği Mengücekli saraylarında himaye gören büyük tabip Abdüllatif el-Bağdadi, bölgedeki tıp ve felsefe çalışmalarının yüksek seviyesini belgeler.'),
  ('Mardin\'de Artuklu hükümdarı Necmeddin İlgazi döneminde temeli atılan Eminüddin Maristanı\'nın (Külliye) içinde cami ve çeşmenin yanı sıra hamam ile şifahanenin yer alması neyi gösterir?', 'Anadolu\'da darüşşifa (hastane) kurma geleneğinin Artuklularla daha 12. yüzyıl başında başladığını', ['Şifahanelerin yalnızca askeri kışlaların içinde gizli olarak kurulduğunu', 'Temizlik ve tıp hizmetlerinin halktan alınan ağır cezalarla yürütüldüğünü', 'Anadolu\'daki ilk hastanenin ancak Osmanlı döneminde açılabildiğini'], '1108-1122 yılları arasına tarihlenen Mardin Eminüddin Külliyesi bünyesindeki maristan (bimaristan), Anadolu\'da Türklerin kurduğu en erken tıp ve sağlık tesisidir.'),
  ('Kemah\'ta Fırat Nehri kıyısında bulunan ve Mengücek Gazi ile hanedan üyelerine ait olduğu kabul edilen tuğla-taş örgülü türbe ve mezar yapıları hangi açıdan önem taşır?', 'Mengücekli Beyliği\'nin ilk kuruluş merkezindeki erken dönem Türk mezar mimarisini belgelemesiyle', ['İçinde Hitit krallarına ait altın maskelerin bulunmuş olmasıyla', 'Anadolu\'da mermerden yapılmış tek üç katlı saray olmasıyla', 'Moğol hükümdarı Hülagü Han tarafından inşa ettirilmiş olmasıyla'], 'Erzincan Kemah\'taki Mengücek Gazi Türbesi ve Behramşah kümbetleri, Karahanlı-Büyük Selçuklu tuğla işçiliğinden Anadolu taş işçiliğine geçişin önemli halkalarıdır.'),
  ('Saltuklu Beyliği topraklarının 1202 yılında Türkiye Selçuklu Sultanı Rükneddin Süleymanşah tarafından ilhak edilmesinin temel dış politika gerekçesi ne olmuştur?', 'Gürcistan seferi öncesinde son Saltuklu beyi Melikşah\'ın itaatte gevşeklik göstermesi ve doğu sınırını güçlendirme ihtiyacı', ['Saltukluların Karadeniz\'de Cenevizlilerle birleşerek Sinop\'a saldırması', 'Erzurum halkının kuraklık nedeniyle Konya Ovası\'na göç etmek istemesi', 'Haçlı donanmasının Fırat Nehri üzerinden Erzurum önlerine ulaşması'], 'Gürcistan Krallığı\'nın Kafkasya ve Doğu Anadolu\'daki baskısını kırmak için sefere çıkan Süleymanşah, 1202\'de Erzurum\'a girerek Saltuklu Beyliği\'ni doğrudan Selçuklu idaresine bağlamıştır.'),
  ('Mardin\'deki Hatuniye ve Zinciriye medreselerinde taç kapının yanından başlayıp avluya dökülen selsebil ve su kanallarının hem suyun doğumunu-akışını-gölete kavuşmasını simgelemesi hangi felsefi anlamı taşır?', 'İnsan ömrünün doğumdan ölüme ve ilahi kaynağa dönüş yolculuğunu suyun döngüsüyle anlatmayı', ['Tüccarların getirdiği kumaşların medrese avlusunda boyanmasını sağlamayı', 'Yangın tehlikesine karşı kütüphane kitaplarını ıslatarak korumayı', 'Öğrencilerin yüzme ve dalgıçlık eğitimi alacağı derin havuz oluşturmayı'], 'Artuklu medreselerindeki \'selsebil\' çeşme-kanal-havuz kurgusu, hem avluyu serinleten iklimsel bir çözüm hem de yaşam-ölüm-ebediyet döngüsünü betimleyen tasavvufi bir semboldür.'),
  ('Danişmendli hükümdarı Emir Gazi\'nin (1104-1134) Büyük Selçuklu Sultanı Sencer ve Abbasi Halifesi Müsterşid-Billah tarafından \'Melik\' unvanı ve siyah sancakla ödüllendirilmesinin sebebi nedir?', 'Haçlılara ve Kilikya Ermenilerine karşı kazandığı zaferlerle Anadolu\'da en güçlü lider konumuna yükselmesi', ['Büyük Selçuklu hazinesine her yıl yüz ton gümüş bağışlamayı taahhüt etmesi', 'Mısır\'daki Fatımi Devleti\'ni yıkarak Kahire\'yi Abbasi adına fethetmesi', 'İpek Yolu üzerindeki tüm gümrük vergilerini Bağdat sarayına bırakması'], 'I. Mesud\'un kayınpederi olan Danişmendli Emir Gazi, Haçlılara vurduğu ağır darbeler ve Anadolu\'daki üstün nüfuzu sebebiyle Halife ve Sultan Sencer tarafından \'Melik\' unvanıyla onurlandırılmıştır.'),
  ('Emir Saltuk Kümbeti\'nin üst kasnak nişlerinde yer alan tavşan, kartal, yılan ve boynuzları arasında insan başı bulunan boğa kabartmaları sanat tarihçilerince hangi takvim geleneğiyle ilişkilendirilir?', 'On İki Hayvanlı Türk Takvimi ve Orta Asya kozmolojik simgeleriyle', ['Mısır firavunlarının ölüler kitabındaki mumyalama sahneleriyle', 'Roma lejyonlarının eyalet sınırlarına diktiği mil taşlarıyla', 'Babil rahiplerinin tufan efsanesini anlatan çivi yazılarıyla'], 'Saltuklu mimarisindeki hayvan figürlü kabartmalar, İslamiyet öncesi Türk bozkır sanatı ile On İki Hayvanlı Türk Takvimi sembollerinin Anadolu taş mimarisindeki devamıdır.'),
  ('Mardin Artukluları döneminde Hüsameddin Timurtaş ve Necmeddin Alpi\'nin bastırdığı büyük boy bakır sikkelerin (dirhem/fels) üzerinde Büyük İskender, Roma imparatorları ya da burç tasvirlerinin yer almasının pratik ticari sebebi nedir?', 'Uluslararası Yakın Doğu pazarlarında yabancı tüccarların aşina olduğu prestijli kalıplarla kabul görmeyi sağlamak', ['Artuklu hanedanının soyunu Makedonya krallarına dayandırma çabası', 'Müslüman halkın resimsiz paraları kullanmayı reddetmesi', 'Darphane ustalarının Arapça yazı yazmayı bilmemesi'], '\'Figürlü Artuklu sikkeleri\' olarak nümismatik tarihinde ün kazanan bu paralar, Kuzey Mezopotamya ile Akdeniz-Avrupa arasındaki yoğun ticarette tanıdık ikonografiyle güven yaratmıştır.'),
  ('Tercan\'daki Mama Hatun Kümbeti\'ni Anadolu\'daki diğer tüm kümbet ve türbelerden mimari plan bakımından ayıran benzersiz özellik nedir?', 'Dilimli gövdeli mezar anıtının dıştan daire biçimli anıtsal bir kuşatma duvarıyla çevrelenmiş olması', ['Tamamen göl ortasındaki kayalık üzerine ahşap direklerle kurulmuş olması', 'Üzerinde sekiz adet ince tuğla minarenin yükseliyor olması', 'Hiçbir kapısı bulunmayıp yalnızca çatıdan merdivenle girilmesi'], 'Ahlatlı Mimar Ebu\'n-Nema bin Mufaddal\'ın eseri olan Mama Hatun Türbesi, içte sekiz dilimli gövde ve onu çepeçevre kuşatan nişli dairesel çevre duvarıyla Anadolu\'da tek örnektir.'),
  ('II. Gıyaseddin Keyhüsrev\'in vefatından sonra küçük yaştaki oğulları II. İzzeddin Keykavus, IV. Kılıçarslan ve II. Alaeddin Keykubad\'ın birlikte sultan ilan edildiği \'Üçlü Saltanat\' devrinde devlet bütünlüğünü koruyan bilge devlet adamı kimdir?', 'Celaleddin Karatay', ['Moğol valisi sıfatıyla Sivas\'ta karargâh kuran Emir Eretna', 'Harzemşah ordusunun Anadolu\'daki bakiyesini yöneten Kayır Han', 'İznik Rum İmparatorluğu ile gizli ittifak yürüten Mihail Paleologos'], 'Atabey ve naib Celaleddin Karatay, 1249-1254 yılları arasında üç kardeş sultan adına hutbe okutup para bastırarak taht kavgasını önlemiş ve iç barışı korumuştur.'),
  ('1277 yılında Memlük Sultanı Baybars\'ın Anadolu\'daki Moğol-İlhanlı güçlerini Elbistan Ovası\'nda bozguna uğratmasına rağmen Anadolu\'da kalmayıp Suriye\'ye dönmesinin yarattığı ağır sonuç ne olmuştur?', 'İlhanlı Hükümdarı Abaka Han\'ın Anadolu\'da sert cezalandırma yapıp Vezir Pervane\'yi idam ettirmesi', ['Memlük ordusunun Konya\'yı yağmalayarak tüm Selçuklu saray arşivlerini Kahire\'ye götürmesi', 'Karamanoğlu beyliğinin Moğollarla birleşerek Memlüklerin Çukurova kalelerini işgal etmesi', 'Trabzon Rum ordusunun Erzurum ve Sivas\'ı ele geçirerek doğu ticaretini tekeline alması'], 'Sultan Baybars kendisine söz veren Selçuklu devlet adamlarından beklediği askeri desteği göremeyince geri dönmüş; öfkelenen İlhanlı Hükümdarı Abaka Han binlerce kişiyi katlettirip Muineddin Pervane\'yi öldürtmüştür.'),
  ('Türkiye Selçuklu Devleti\'nde vakıflar hariç devlet kurumlarının gelir-giderlerini teftiş eden ve yolsuzlukları araştıran \'Divan-ı İşraf\'ın başındaki görevliye ne ad verilirdi?', 'Müşrif-i Memâlik', ['Reisü\'l-Bahr', 'Melikü\'l-Ümerâ', 'Emir-i Ahur'], 'Divan-ı İşraf devletin idari ve mali teftiş kurumudur; başındaki Müşrif-i Memâlik, vilayetlere gönderdiği müşrifler aracılığıyla memurları ve mali işlemleri denetlerdi.'),
  ('Türkiye Selçuklu saray protokolünde vezirden sonra en nüfuzlu kişilerden biri olan, hükümdar ile divan ve halk arasındaki iletişimi düzenleyip elçileri kabul törenine hazırlayan görevli kimdir?', 'Hâcibü\'l-Hüccâb', ['Sınır kalelerindeki gözetleme kulelerini denetleyen Dizdar', 'Şer\'i davalarda kadıların verdiği hükümleri temyiz eden Müftü', 'Posta güvercinleri ve ulak menzillerini idare eden Sahib-i Berid'], 'Hâciplerin başı olan Hâcibü\'l-Hüccâb, saray teşrifatını yöneten, merasimlerde düzeni sağlayan ve elçileri hükümdarın huzuruna çıkaran üst düzey protokoldür.'),
  ('Türkiye Selçuklu şehir yönetiminde özellikle Konya, Kayseri ve Sivas gibi büyük ticaret merkezlerinde vergi toplama, asayişe yardım etme ve yerli halk ile saray arasında aracılık yapma görevini üstlenen zümre yöneticisi kimdir?', 'İğdişbaşı', ['Sınır boylarında akınlar düzenleyen Türkmen beyi Uçbeyi', 'Kalelerin burçlarını ve silah depolarını bekleyen Kale Kethüdası', 'Darphanelerde gümüş dirhemlerin ayarını kontrol eden Sikkezen'], 'Türkiye Selçuklu şehirlerine özgü önemli bir kurum olan \'İğdişler\' (farklı etnik kökenli ebeveynden doğan, iki kültür ve dili bilen şehirli tüccar/idareci zümre), başlarındaki İğdişbaşı aracılığıyla mali ve kentsel idarede kilit rol oynamıştır.'),
  ('Türkiye Selçuklularında üstün devlet hizmeti görülen devlet adamlarına veya komutanlara mirî araziden mülkiyet hakkıyla bağışlanan \'mülk toprakların\' sahiplerince genellikle vakfa dönüştürülmesinin başlıca nedeni nedir?', 'Hem hayır eseri yaşatmak hem de arazinin müsadere veya mirasla parçalanmasını önlemek', ['Vakıf topraklarında çalışan köylülerden iki kat daha fazla öşür vergisi alabilmek', 'Devletin askeri seferlerine katılma zorunluluğunu köylülerin üzerine devretmek', 'Tarım arazilerini imara açarak yabancı tüccarlara yüksek bedelle satabilmek'], 'Devlet ricali sahip oldukları mülk toprakları medrese, han ve cami vakıflarına bağlayarak hem kalıcı sosyal kurumlar kurmuş hem de İslam hukukunda dokunulmaz olan vakıf statüsüyle arazinin bütünlüğünü güvenceye almıştır.'),
  ('Türkiye Selçuklu ordusunda kale kuşatmalarında surları yıkmak için ağır taş gülleler fırlatan mancınık ve arrâde ustalarına askeri terminolojide ne ad verilirdi?', 'Mancınıkçı ve Neftçi bölükleri', ['Sadece nehir geçişlerinde salları birbirine bağlayan Köprücüler', 'Savaş meydanında yaralı atları tedavi eden gezici Baytarlar', 'Öncü süvari kollarının önünde davul çalan Nevbetçiler'], 'Antalya, Sinop ve Alanya gibi çok sağlam surlu kalelerin fethinde Selçuklu ordusundaki uzman mancınıkçılar, lağımcılar ve Rum ateşi/neft atan neftçiler belirleyici rol oynamıştır.'),
  ('Türkiye Selçuklu sultanlarının alaylarda ve savaş meydanlarında başlarının üzerinde taşınan, üzerinde Kur\'an ayetleri veya hükümdarlık simgeleri işlenmiş atlas kumaştan saltanat şemsiyesine ne denirdi?', 'Çetr', ['Hükümdar otağının çevresine çekilen kırmızı perde Serâperde', 'Ok ve yaydan oluşan geleneksel Oğuz boy nişanı Tîr ü Kemân', 'Eyer örtüsü olarak merasimlerde omuzda taşınan Gâşiye'], 'Siyah veya sarı atlas kumaştan yapılan \'Çetr\', sultanın gökyüzü altındaki egemenliğini temsil eder; savaşta çetrin dik durması ordunun moral kaynağı, devrilmesi ise bozgun işareti sayılırdı.'),
  ('1086 yılında Kutalmışoğlu Süleymanşah\'ın Antakya\'yı fethettikten sonra Suriye Selçuklu Meliki Tutuş ile yaptığı Ayn Seylem Savaşı\'nı kaybedip ölmesi üzerine Büyük Selçuklu Sultanı Melikşah Süleymanşah\'ın oğullarına ne yapmıştır?', 'Kılıçarslan ve Kulan Arslan\'ı İsfahan sarayına götürerek gözetim altında tutmuştur', ['Her iki şehzadeyi de İznik tahtına ortak sultan olarak derhal atamıştır', 'Şehzadeleri Bizans İmparatoru Aleksios Komnenos\'a rehine olarak göndermiştir', 'Mısır Fatımi halifesiyle anlaşarak çocukları Kahire medreselerine yerleştirmiştir'], 'Anadolu\'da bağımsız bir kolun güçlenmesini istemeyen Sultan Melikşah, Süleymanşah\'ın oğulları Kılıçarslan ve Davud Kulan Arslan\'ı İsfahan\'a götürmüş; Kılıçarslan ancak 1092\'de Melikşah ölünce İznik\'e dönüp tahta çıkmıştır.'),
  ('Sultan Süleymanşah\'ın 1086\'da ölümünden I. Kılıçarslan\'ın 1092\'de İznik\'e gelişine kadar geçen altı yıllık fetret devrinde İznik\'te devleti vekâleten yönetip Marmara kıyılarına akınlar düzenleyen komutan kimdir?', 'Ebu\'l-Kasım', ['İzmir\'de tersane kurup Ege adalarını vuran Çaka Bey', 'Niksar ve Tokat havzasında beylik kuran Danişmend Gazi', 'Malazgirt\'te Bizans saflarından Türklere geçen Romen Diyojen'], 'Süleymanşah Suriye seferine çıkarken İznik\'te vekil (naib) bıraktığı Ebu\'l-Kasım, 1086-1092 arasında devleti ayakta tutmuş ve İznik gölü ile Gemlik\'te donanma kurma girişiminde bile bulunmuştur.'),
  ('I. Gıyaseddin Keyhüsrev\'in 1196\'da kardeşi Rükneddin Süleymanşah\'a tahtı bırakmak zorunda kaldığında bir süre İstanbul\'da Bizans sarayında misafir kalması ve soylu Mavrozomes ailesinden evlenmesi neyi gösterir?', 'Selçuklu-Bizans ilişkilerinin yalnız savaştan ibaret olmayıp sıkı diplomatik ve hanedan temasları içerdiğini', ['Türkiye Selçuklu tahtına çıkabilmek için Bizans imparatorundan onay alınmasının şart olduğunu', 'Selçuklu şehzadelerinin tamamının eğitim görmek üzere İstanbul okullarına gönderildiğini', 'İki devlet arasında sınırların kaldırılarak ortak bir gümrük birliği kurulduğunu'], 'Orta Çağ Anadolu\'sunda Türkiye Selçuklu ve Bizans sarayları arasında savaşların yanı sıra siyasi sığınma, dostluk, evlilik ve karşılıklı askeri yardımlaşma örnekleri sıkça yaşanmıştır.'),
  ('1211 yılında Alaşehir (Filadelfiya) Savaşı\'nda İznik Rum İmparatoru I. Theodoros Laskaris\'in ordusunu yendikten sonra savaş meydanında şehit düşen Türkiye Selçuklu sultanı kimdir?', 'I. Gıyaseddin Keyhüsrev', ['Miryokefalon\'da Bizans ordusunu pusuya düşüren II. Kılıçarslan', 'Habur Irmağı\'nı geçerken boğularak ölen I. Kılıçarslan', 'Kayseri Keykubadiye Sarayı\'ndaki ziyafette zehirlenen I. Alaeddin Keykubad'], 'Eski dostu III. Aleksios lehine İznik Rum İmparatoru Laskaris üzerine yürüyen I. Gıyaseddin Keyhüsrev, 1211 Alaşehir Muharebesi\'ni kazanmış ancak dikkatsizce ileri atıldığında bir Frenk askeri tarafından şehit edilmiştir.'),
  ('Sultan I. Alaeddin Keykubad\'ın saltanatının başlarında Konya ve Kayseri\'deki en kudretli emirleri bir gecede tutuklatıp mallarını müsadere ettirmesi hangi iç politika amacına yöneliktir?', 'Taht üzerinde vesayet kurmaya alışmış büyük emirlerin gücünü kırıp mutlak merkezi otoriteyi kurmak', ['Devletin tüm askeri komuta kademesini Moğol generallerine teslim etmeye zemin hazırlamak', 'İkta topraklarını dağıtarak köylülerin vergisiz özel çiftlikler kurmasını sağlamak', 'Abbasi Halifesi\'nin gönderdiği ferman uyarınca tüm Türkmen beylerini cezalandırmak'], 'Ağabeyi I. İzzeddin Keykavus döneminden beri güçlenen ve sultanları yönlendirmeye kalkan Seyfeddin Ayaba gibi nüfuzlu emirleri tasfiye eden Alaeddin Keykubad, sarsılmaz bir merkezi devlet disiplini kurmuştur.'),
  ('Türkiye Selçuklu ordusunda savaş sırasında ordunun önünde giderek düşman hakkında istihbarat toplayan ve ilk sıcak teması kuran öncü süvari birliğine ne ad verilirdi?', 'Talîa', ['Ordunun en gerisinde ağırlıkları ve yaralıları koruyan Dümdâr', 'Merkezde sultanın sancağı etrafında etten duvar ören Kalb', 'Kale duvarlarının altından tünel kazarak sur çökerten Lağımcı'], 'Klasik Selçuklu beşli savaş nizamında (merkez/kalb, sağ kol/meymene, sol kol/meysere, öncü/talîa, artçı/sâka-dümdâr) keşif ve ilk vuruş görevini \'talîa\' birlikleri üstlenirdi.'),
  ('Kösedağ bozgunu sırasında Sultan II. Gıyaseddin Keyhüsrev savaş meydanını terk edip Antalya\'ya çekilirken, Amasya Kadısı ile birlikte Baycu Noyan\'ın karargâhına giderek barış antlaşması imzalayan ve Anadolu\'yu topyekûn kırımdan kurtaran vezir kimdir?', 'Mühezzibüddin Ali', ['Devlet adamlarını haksız yere idam ettiren Sadeddin Köpek', 'Afyonkarahisar\'da kendi hanedanını kuran Sahip Ata Fahreddin Ali', 'İlhanlı hükümdarı Abaka Han tarafından öldürülen Muineddin Pervane'], 'Vezir Mühezzibüddin Ali, Moğol komutanı Baycu Noyan\'a değerli hediyelerle giderek yıllık vergi karşılığında barış yapmış ve Türkiye Selçuklu Devleti\'nin tamamen ortadan kaldırılmasını önlemiştir.'),
  ('Türkiye Selçuklularında vilayetlerdeki şer\'i ve örfi vergilerin dışında, ikta veya vilayet halkının kendi yerel idari giderlerini ve gelen memurların konaklama masraflarını karşılamak üzere ödediği örfi yükümlülükler neyi yansıtır?', 'Taşra bürokrasisinin yerinde finansmanıyla merkezi hazine üzerindeki yükün hafifletildiğini', ['Merkezi yönetimin vilayetlerden hiçbir vergi almayıp yalnız başkent gelirleriyle yetindiğini', 'Köylülerin vergilerini para veya ürün yerine yalnız kale duvarı örerek ödediğini', 'Yabancı tüccarların taşra kasabalarında ücretsiz konaklamasının yasaklandığını'], '\'avârız-ı divaniyye\' ve \'rusûm-ı örfiyye\' kapsamındaki konaklama (nüzul) ve yerel hizmet payları, taşradaki kamu hizmetlerinin aksamadan yürütülmesini sağlamıştır.'),
  ('Selçuklu taşra idaresinde \'Melik\' unvanıyla Sivas, Malatya, Erzincan veya Ankara gibi eyaletlere gönderilen şehzadelerin kendi adlarına para bastıramamaları ve yabancı devletlerle savaş-barış kararı alamamaları neyi amaçlar?', 'Şehzadeler yönetim tecrübesi kazanırken merkezi devlet egemenliğinin parçalanmasını engellemeyi', ['Taşra şehirlerinde ticari alışverişin yalnızca takas usulüyle yürütülmesini sağlamayı', 'Meliklerin askeri eğitim almaktan uzak tutulup sadece medrese ilmiyle uğraşmasını', 'Vilayetlerde toplanan vergilerin tamamının komşu beyliklere hibe edilmesini'], 'II. Kılıçarslan dönemindeki aşırı yetkili paylaşımın yol açtığı sarsıntıdan ders alan I. Gıyaseddin Keyhüsrev ve halefleri, meliklerin yetkilerini sınırlandırarak merkeziyetçi yapıyı güçlendirmişlerdir.'),
  ('Türkiye Selçuklu askeri ikta sisteminde bir ikta sahibinin ölmesi hâlinde toprağın doğrudan miras gibi bölünmeyip oğulları askerliğe elverişliyse hizmet şartıyla yeniden tevcih edilmesi neyi korumuştur?', 'Toprağın mülkleşmesini önleyerek sipahi ordusunun savaşa hazırlık kapasitesini', ['Köylü ailelerinin her kuşakta başka bir vilayete göç ettirilmesi kuralını', 'İkta gelirlerinin tamamının yabancı paralı asker komutanlarına aktarılmasını', 'Tarım arazilerinin ekilmeyerek sadece avlak olarak saklanması geleneğini'], 'Devlet mirî toprağın mülkiyetini elinde tutarak iktanın feodal malikâneye dönüşmesini önlemiş, ancak sipahi çocuğuna hizmet karşılığı öncelik tanıyarak askeri geleneğin babadan oğula sürmesini teşvik etmiştir.'),
  ('Selçuklu donanmasının Alanya ve Sinop tersanelerinde inşa ettiği \'kadırga ve şelandi\' tipi gemilerin hem kürekle hem yelkenle hareket edebilecek biçimde tasarlanmasının sebebi nedir?', 'İç denizlerin değişken rüzgârlarında ve kıyı çıkarma harekâtlarında yüksek manevra kabiliyeti sağlamak', ['Okyanus aşırı seferlerde aylarca karaya uğramadan binlerce top taşıyabilmek', 'Nehir yataklarından yukarı tırmanarak Orta Anadolu göllerine ulaşabilmek', 'Kış fırtınalarında gemileri tamamen suyun altına indirerek gizleyebilmek'], 'Akdeniz ve Karadeniz gibi iç denizlerde rüzgârın kesildiği anlarda kürek gücüyle hızla bordalama ve kıyıya asker çıkarma üstünlüğü sağlayan kadırga ve at taşıyan şelandiler Selçuklu filosunun belkemiğiydi.'),
  ('Ünlü Endülüslü mutasavvıf Muhyiddin İbnü\'l-Arabî\'nin üvey oğlu ve en seçkin öğrencisi olup Konya\'da kurduğu külliyede hem hadis ilmini hem de Vahdet-i Vücûd düşüncesini sistemleştiren âlim kimdir?', 'Sadreddin Konevî', ['Sivas Gök Medrese\'de fıkıh dersleri veren Kadı Siraceddin Urmevî', 'Kubadabad Sarayı\'nın çini programını yöneten Sadeddin Köpek', 'El-Evâmirü\'l-Alâiyye adlı Selçuklu tarihini yazan İbn Bîbî'], 'Mevlânâ\'nın da yakın dostu olan Sadreddin Konevî (ö. 1274), Konya\'yı İslam dünyasının en üst düzey felsefi tasavvuf ve hadis merkezlerinden biri haline getirmiştir.'),
  ('Beş gözlü kemerli galerilerden oluşan \'Alanya Tersanesi\'nin cephesi ve konumu planlanırken gemi inşa ustalarının yıl boyu verimli çalışabilmesi için hangi mühendislik detayı gözetilmiştir?', 'Gün ışığından en uzun süre yararlanacak ve kış fırtınalarından korunacak güney-doğu yönelimi', ['Nehir sularının getirdiği kumlarla gemilerin karaya kolayca oturmasını sağlayan sığ ağız', 'Yalnızca geceleri meşale ışığında gizlice gemi yapılabilmesi için penceresiz yer altı planı', 'Dalga boyunun en yüksek olduğu açık burun ucuna kütük indirme rampası kurulması'], '1227\'de yapılan beş tonozlu gözden ibaret Alanya Tersanesi, hem sert lodos dalgalarından korunacak kuytu koya oturtulmuş hem de kademeli tonoz pencereleriyle içerinin gün boyu aydınlık kalması sağlanmıştır.'),
  ('Konya\'da Vezir Sahip Ata Fahreddin Ali tarafından hadis ilmi okutulmak üzere 1264 civarında yaptırılan ve taç kapısında kurdele gibi kıvrılarak yükselen kabartma Yasin ile Fetih sureleri bulunan yapı hangisidir?', 'İnce Minareli Medrese', ['Fıkıh eğitimi için Bedreddin Muslih tarafından kurulan Sırçalı Medrese', 'Kubbesi firuze çinilerle kaplı kapalı avlulu Karatay Medresesi', 'Mevlânâ\'nın türbesi etrafında şekillenen Yeşil Kubbe Dergâhı'], 'Mimarı Kelük bin Abdullah olan Konya İnce Minareli Medrese, taç kapısındaki barok etkili plastik taş oyma yazı kuşakları ve sırlı tuğlalı minaresiyle Selçuklu taş sanatının en özgün örneklerindendir.'),
  ('İnce Minareli Medrese ve Sivas Gök Medrese gibi ünlü Selçuklu eserlerinin kitabelerinde başmimar olarak imzası bulunan 13. yüzyılın büyük mimar-sanatkârı kimdir?', 'Kölük (Kelük) bin Abdullah', ['Divriği Ulu Camii\'nin taş kapılarını yontan Ahlatlı Hürremşah', 'Alanya Kızılkule ve Tersanesi\'ni inşa eden Halepli Ebu Ali Reha', 'Erzurum Çifte Minareli Medrese\'yi tasarlayan Konyalı Kaluyan'], 'Vezir Sahip Ata Fahreddin Ali\'nin baniliğini yaptığı Konya Sahip Ata Külliyesi, İnce Minareli Medrese ve Sivas Gök Medrese (Konyalı Kaluyan ile ilişkili üslup çevresiyle beraber Konya yapılarında bizzat) Kölük bin Abdullah\'ın dehasını taşır.'),
  ('I. Gıyaseddin Keyhüsrev döneminden başlayarak 1280 yılına kadarki Türkiye Selçuklu tarihini Farsça olarak kaleme alan ve dönemin en kapsamlı birinci el kaynağı sayılan \'El-Evâmirü\'l-Alâiyye fi\'l-Umûri\'l-Alâiyye\' adlı eserin yazarı kimdir?', 'İbn Bîbî', ['Müsâmeretü\'l-Ahbâr adlı eseriyle Moğol devrini anlatan Kerimüddin Aksarayî', 'Râhatü\'s-Sudûr adlı Büyük Selçuklu tarihini sunan Muhammed Râvendî', 'Câmiü\'t-Tevârîh adlı genel dünya tarihini derleyen Reşîdüddîn Fazlullah'], 'Selçuklu Divan-ı Tuğra başkanı (Münşi) Hüseyin bin Muhammed İbn Bîbî\'nin Alaeddin Ata Melik Cüveynî adına yazdığı \'El-Evâmirü\'l-Alâiyye\', Türkiye Selçuklu siyasi ve kültür tarihinin en temel kaynağıdır.'),
  ('Özellikle 1243 Kösedağ Savaşı sonrasındaki İlhanlı tahakkümü yıllarını, mali sömürüyü ve Selçuklu devletinin çöküş evresini (1323\'e dek) içeriden gözlemlerle anlatan \'Müsâmeretü\'l-Ahbâr\' adlı tarih eserinin müellifi kimdir?', 'Kerîmüddin Mahmud Aksarayî', ['Anadolu şehirlerindeki Ahi zaviyelerini gezen Faslı seyyah İbn Battuta', 'Artuklu ve Zengî tarihini Arapça kaleme alan İbnü\'l-Esîr', 'Danişmend Gazi\'nin destanlarını derleyen Tokatlı Arif Ali'], 'Selçuklu divan kâtiplerinden Kerîmüddin Mahmud Aksarayî\'nin yazdığı \'Müsâmeretü\'l-Ahbâr ve Müsâyeretü\'l-Ahyâr\', İbn Bîbî\'nin bıraktığı yerden sonrasını aydınlatan en önemli yerli kroniktir.'),
  ('Antalya ile Isparta-Burdur hattındaki kervan yolunda I. İzzeddin Keykavus döneminde yaptırılan \'Evdir Han\'ı Anadolu\'daki pek çok handan plan bakımından ayıran mimari özelliği nedir?', 'Kapalı kışlık bölümü bulunmayıp sadece dört eyvanlı geniş açık avludan ve revaklardan oluşması', ['Tamamen yer altına oyulmuş üç katlı kaya mahzenlerinden meydana gelmesi', 'Dış duvarlarında mermer yerine yalnız ahşap kütüklerin kullanılmış olması', 'Ortasında gemilerin yanaşabildiği yapay bir su kanalının yer alması'], 'Akdeniz kıyısının ılıman kış ikliminde yer alan Antalya Evdir Han (1215-1219), soğuk yayla hanlarındaki kapalı-tonozlu barınak kısmına ihtiyaç duymadan yalnızca revaklı açık avlu şemasıyla inşa edilmiştir.'),
  ('Çini sanatında yedi ayrı rengin sır altına ve sır üstüne uygulanıp fırında iki kez pişirilmesiyle elde edilen ve özellikle Alaeddin Köşkü\'nde örnekleri bulunan üstün saray çini tekniği hangisidir?', 'Mînâî tekniği', ['Kırmızı hamurlu toprağın sırsız kalıplara basıldığı Terrakota tekniği', 'Taş levhaların arasına kurşun dökülerek birleştirildiği Vitray tekniği', 'Islak alçı üzerine toprak boyalarla resim yapılan Fresk tekniği'], 'Rey ve Kaşan ekolünden gelişip Konya Alaeddin (Kılıçarslan) Köşkü\'nde zarif atlı ve bağdaş kurmuş figürlerle uygulanan \'mînâî\' tekniği, çift fırınlama gerektiren en zahmetli çok renkli çini sanatıdır.'),
  ('Selçuklu dönemi Anadolu ihraç malları incelendiğinde Avrupalı ve İslam dünyası tüccarlarının kumaş boyamakta sabitleyici (mordan) madde olarak Anadolu\'dan tonlarca satın aldığı en stratejik maden ürünü hangisidir?', 'Şap madeni', ['Sadece porselen hamurunda kullanılan beyaz kaolin kili', 'Cam üfleme atölyelerinde eritilen kuvars kumu', 'Saat zembereklerinin yapımında aranan nikel cevheri'], 'Şebinkarahisar ve Kütahya (Gediz) ocaklarından çıkarılan \'şap\', Orta Çağ Avrupa tekstil sanayisinde boyanın kumaşa sabitlenmesi için vazgeçilmez olduğundan Anadolu\'nun bir numaralı maden ihracatıydı.'),
  ('I. Alaeddin Keykubad devrinde Alanya\'dan Konya istikametine giden dağlık kervan yolunda Alara Kalesi eteğine yaptırılan \'Alara Han\'ın iç planında yolcu odalarının koridora, hayvan ahırlarının ise dış çevre galerisine ayrılması neyi amaçlar?', 'İnsan konforu ve mahremiyeti ile yük hayvanlarının bakımını aynı çatı altında hijyenik biçimde ayırmayı', ['Yolcuların kendi atlarını görmesini engelleyerek han yönetiminin kira geliri almasını', 'Hayvanların dış duvarları ısıtmasıyla iç odalarda ateş yakma ihtiyacını kaldırmayı', 'Sadece yaya seyyahların hana alınmasını ve atlı kervanların dışarıda beklemesini'], '1231 tarihli Alara Han, avlusuz eşodaklı planıyla ortadaki aydınlık salonda yolcu hücrelerini, onu çepeçevre saran dış koridorda ise binek hayvanlarını barındıran özgün bir mimari çözümdür.'),
  ('Konya ile Beyşehir arasındaki yol üzerinde Vezir Sadeddin Köpek tarafından 1235-1236 yıllarında yaptırılan ve hem yazlık hem kışlık bölümleriyle Sultan hanları ölçeğinde tasarlanan kervansaray hangisidir?', 'Zazadin Hanı', ['Aksaray-Nevşehir yolunda Hoca Mesud\'un yaptırdığı Ağzıkara Han', 'Kayseri-Malatya güzergâhında Celaleddin Karatay\'ın kurduğu Karatay Han', 'Burdur-Antalya geçidinde Gıyaseddin Keyhüsrev\'in inşa ettirdiği İncir Han'], 'Konya\'nın doğu-kuzeydoğu çıkışındaki Tömek köyü yakınında bulunan Zazadin (Sadeddin) Hanı, iki renkli taş işçiliği ve kitabeleriyle Sadeddin Köpek\'in günümüze ulaşan en önemli mimari eseridir.'),
  ('Tokat\'ta Yeşilırmak üzerinde 1250 yılında Üçlü Saltanat devrinde yaptırılan \'Hıdırlık Köprüsü\'nün kitabesinde üç kardeş sultanın (II. İzzeddin Keykavus, IV. Kılıçarslan, II. Alaeddin Keykubad) adlarının birlikte yazılması neyin belgesidir?', 'Ortak saltanat uzlaşısının bayındırlık eserlerine resmi protokol olarak yansıdığının', ['Köprünün her bir gözünün ayrı bir şehzadenin şahsi mülkü sayıldığının', 'Ülkenin üç ayrı bağımsız krallığa bölünüp sınırın Yeşilırmak çizildiğinin', 'İlhanlı hükümdarının Türkçe ve Arapça kitabe yazılmasını yasakladığının'], 'Celaleddin Karatay\'ın devlet adamlığıyla kurulan Üçlü Saltanat (1249-1254) döneminde paralar gibi Tokat Hıdırlık Köprüsü kitabesi de üç kardeş sultanın ortak adını taşıyan somut bir tarih vesikasıdır.'),
  ('Konya-Isparta güzergâhında Beyşehir Gölü çıkışında yer alan ve Selçuklu çini-taş devşirme malzemeleriyle de onarılan taş köprü ve su bendi geleneğinin yanında, Konya-Aksaray yolundaki \'Obruk Hanı\' adını hangi coğrafi oluşumdan almıştır?', 'Hemen bitişiğinde yer alan derin doğal çöküntü gölünden', ['Kervansarayın kubbesinde kullanılan delikli volkanik sünger taşından', 'Yolculara su çekmek için yüz metre kazılan sarmal merdivenli kuyudan', 'Kış aylarında rüzgâr uğultusunu kesen yüksek yarım daire rüzgârlıktan'], 'Kızören Obruğu\'nun (doğal karstik çöküntü gölü) hemen kıyısına kurulan Obruk Hanı, kurak Konya bozkırında tatlı su kaynağının yanına menzil hanı yerleştirme zekâsını yansıtır.'),
  ('Sivas\'ta Muzaffereddin Burucirdî tarafından 1271\'de yaptırılan \'Buruciye Medresesi\' açık avlulu ve dört eyvanlı simetrik planıyla Anadolu Selçuklu mimarisinde hangi niteliğiyle öne çıkar?', 'Plan simetrisi ve oran uyumu açısından Anadolu\'daki en dengeli medreselerden biri olmasıyla', ['Hiçbir taş bezeme içermeyen sade kerpiç duvarlarla inşa edilmiş bulunmasıyla', 'Üç katlı öğrenci koğuşlarıyla yüzlerce oda barındıran tek yapı olmasıyla', 'Deniz feneri biçiminde tasarlanmış dört adet köşe minaresine sahip olmasıyla'], 'İran\'ın Hemedan yakınlarındaki Burucird kentinden gelen tüccar-âlim Muzaffereddin Burucirdî\'nin fizik, kimya ve gökbilim çalışmaları için yaptırdığı Buruciye Medresesi, kusursuz simetrik dört eyvanlı planıyla ünlüdür.'),
  ('Selçuklu dönemi tıp bilginlerinden Hacı Paşa\'dan önce, 13. yüzyıl başında I. İzzeddin Keykavus ve I. Alaeddin Keykubad\'ın özel hekimliğini de yapan, şifahanelerde hocalık yürüten \'Ekmeleddin Müeyyed el-Nahcuvânî\' gibi tabiplerin varlığı neyi kanıtlar?', 'Saray ve darüşşifalarda İslam dünyasının en seçkin hekim kadrolarının istihdam edildiğini', ['Anadolu\'da hekimlik mesleğinin yalnızca gayrimüslim rahiplerin tekelinde bulunduğunu', 'Tıp eğitiminin medreselerden çıkarılıp sadece berber dükkânlarına bırakıldığını', 'Hastaların tedavisinde bitkisel ilaçlar yerine yalnızca muska kullanıldığını'], 'Mevlânâ\'nın da dostu olan Tabip Ekmeleddin, Gazanfer Tebrizî ve Hubeyş bin İbrahim et-Tiflisî (\'Kâmilü\'s-Sınâa\' ve Türkçe-Farsça tıp/ilaç eserleri çevirmeni) Türkiye Selçuklu tıbbının yüksek bilimsel düzeyini gösterir.'),
  ('Kayseri-Malatya kervan yolu üzerinde Elbistan ayrımında Emir Celaleddin Karatay tarafından 1240-1241 yıllarında tamamlanan \'Karatay Hanı\', taç kapısı ve türbe mukarnaslarında hangi şaşırtıcı bezeme unsurlarını barındırır?', 'Fil, boğa, aslan, kuş ve insan başlarından oluşan zengin figürlü taş kabartmaları', ['Kadırga yelkenleri ve deniz kızı figürlerinden meydana gelen mozaik panoları', 'Hitit hiyeroglif yazısıyla kazınmış bereket tanrısı ve üzüm salkımı rölyeflerini', 'Avrupa şövalyelerinin zırh ve kalkan armalarını gösteren mermer levhaları'], 'Kayseri Bünyan yakınlarındaki Karatay Kervansarayı, İslam dünyasındaki en ayrıntılı vakfiyelerden birine sahip olmasının yanında boğa, fil, tavşan ve insan figürlü taş yontularıyla sanat tarihi açısından benzersizdir.'),
  ('Türkiye Selçuklu şehirlerinde sur dışına taşan nüfus ve ticaret canlanmasıyla oluşan, cami, zaviye, fırın ve pazar yerlerinin etrafında gelişen yeni açık mahalle dokusuna şehircilikte ne ad verilmiştir?', 'Rabad (Dış şehir / Varos öncesi açık mahalleler)', ['Hükümdar sarayının ve darphanenin korunduğu yüksek İç Kale (Ahmedek)', 'Yalnızca askeri süvari birliklerinin çadır kurduğu kışla meydanı Ordugâh', 'Yabancı gemicilerin karaya çıkmadan mal boşalttığı gümrüklü Liman Kapanı'], '13. yüzyılın güvenlik ve refah ortamında Konya, Sivas ve Kayseri surlara sığmamış; iç kale (\'ahmedek\') ve sur içi şehrin (\'şehristan\') dışına taşan geniş, bahçeli \'rabad\' mahalleleri büyümüştür.'),
  ('Selçuklu savunma mimarisinde şehir surlarının en yüksek ve stratejik köşesine kurulan, iç kalenin de içinde son direnek noktası ve komuta merkezi işlevi gören müstahkem bölüme ne ad verilirdi?', 'Ahmedek', ['Kervanların şehir girişinde konakladığı açık avlu Menzilhane', 'Su kanallarının mahalle çeşmelerine dağıtıldığı hazne Maksem', 'Okçuların nişan talimi yaptığı yüksek taş sütun Nişantaşı'], 'Konya, Alanya, Antalya ve Sivas sur kitabelerinde geçen \'Ahmedek\' (Ehmedek), şehrin en korunaklı iç kale tahkimatı ve garnizon komutanlığının merkez kalesidir.'),
  ('Aksaray-Nevşehir kervan yolu üzerinde 1231-1237 yılları arasında Hoca Mesud bin Abdullah tarafından yaptırılan ve zengin bir tüccarın bile sultanlar ölçüsünde anıtsal han kurabildiğini gösteren kervansaray hangisidir?', 'Ağzıkara Han', ['Konya-Beyşehir yolunda Sadeddin Köpek\'in kurduğu Zazadin Han', 'Isparta Eğirdir Gölü kenarında yükselen Gıyaseddin Keyhüsrev Hanı', 'Sivas-Erzincan dağ geçidinde Mengüceklilerden kalan Mama Hatun Hanı'], 'Aksaray yakınlarındaki Ağzıkara Han, bir sultan veya vezir değil, varlıklı bir hayırsever olan Hoca Mesud tarafından yaptırılmış olmasıyla Selçuklu sivil sermayesinin ulaştığı refahı kanıtlar.'),
  ('Selçuklu taş ve çini bezemelerinde sıklıkla görülen, ucu kıvrık çatallı yaprak/kanat biçimindeki \'rûmî\' motifi adını nereden almıştır?', 'Anadolu (Diyâr-ı Rûm) Selçuklu sanatkârlarınca geliştirilip İslam dünyasında \'Anadolu üslubu\' olarak tanınmasından', ['Doğu Roma kiliselerindeki haç ve üzüm salkımı kabartmalarının birebir kopyalanmasından', 'Motifi ilk çizen nakkaşın Mevlânâ Celâleddin-i Rûmî\'nin müridi olmasından', 'Yalnızca Rum asıllı taş ustalarının lonca damgası olarak kullanılması şartından'], 'Kökeni Orta Asya hayvan üslubundaki kanat ve gaga kıvrımlarına dayanan bu bitkisel-zoomorfik motif, Türkiye Selçuklularında (Diyâr-ı Rûm) klasik formuna ulaştığı için tüm İslam sanatında \'Rûmî\' (Anadolu\'ya ait) adıyla anılmıştır.'),
  ('Selçuklu döneminden günümüze ulaşan \'Cevâhirnâme, Baytarnâme ve Bâznâme\' türündeki uygulamalı bilim eserleri sırasıyla hangi üç uzmanlık alanını konu edinmektedir?', 'Değerli taş ve madenleri, at/hayvan hekimliğini ve yırtıcı av kuşlarının bakımını', ['Deniz rüzgârlarını, gemi yelken dokumacılığını ve liman gümrük hesaplarını', 'Şifalı bitkileri, göz katarakt ameliyatlarını ve kırık çıkık sargılarını', 'Yıldız tutulmalarını, arazi sulama kanallarını ve güneş saati çizimlerini'], 'Kültür ve bilim tarihinde \'Cevâhirnâme\' kıymetli taş ve mineralleri, \'Baytarnâme\' özellikle savaş atlarının hastalık ve tedavisini (veterinerlik), \'Bâznâme\' ise doğan ve şahin gibi av kuşlarının eğitimini inceler.'),
  ('Kayseri Tuzhisar Sultan Hanı\'nın avlu ortasındaki köşk mescidini taşıyan taş kemerlerin yüzeyine işlenmiş birbirine bakan kıvrımlı çift ejder (evren) kabartması Türk sanatında neyi simgeler?', 'Kötülüklerden koruyucu tılsımı, kudreti ve evrensel bolluk-bereket döngüsünü', ['Çin İmparatorluğu\'na her yıl ödenen ipek vergisinin resmi mührünü', 'Kervansarayın zemin katında zehirli sürüngenlerin bulunduğuna dair uyarıyı', 'Haçlı şövalyelerine karşı kazanılan deniz zaferinin ganimet nişanını'], 'Orta Asya Türk kozmolojisinde gök çarkını ve su-bereketi çeviren \'Evren\' (ejder), Selçuklu kervansaray ve şifahanelerinde kötülüğü kovan (apotropaik) ve şifa/bolluk getiren koruyucu simge olarak işlenmiştir.'),
  ('Selçuklu dönemi bakır, tunç ve pirinçten yapılmış şamdan, buhurdan, ayna ve hokkalarda oyulan yuvanın içine gümüş veya altın tel/levha çakılarak yapılan maden süsleme tekniğine ne ad verilir?', 'Kakma', ['Toprak kalıplara erimiş cam üflenerek şekil verilen Çeşmibülbül tekniği', 'Ahşap yüzeylerin yumurta akı ve alçıyla kaplanıp boyandığı Edirnekârî', 'Su yüzeyine serpilen toprak boyaların kâğıda aktarıldığı Ebru sanatı'], 'Musul ve Konya-Erzincan maden atölyelerinde zirveye çıkan tunç ve pirinç eşya üzerine gümüş/altın \'kakma\' tekniği, yazı kuşakları ve burç figürleriyle Selçuklu el sanatlarının en lüks ihraç kalemlerindendir.'),
  ('Karaman merkezde 1381-1382 yıllarında Osmanlı Padişahı I. Murad\'ın kızı ve Karamanoğlu Alâeddin Ali Bey\'in eşi olan Nefise Melek Sultan tarafından Mimar Hoca Ahmed bin Numan\'a yaptırılan ünlü yapı hangisidir?', 'Hatuniye Medresesi', ['Sivas merkezde İlhanlı vezirince yaptırılan Çifte Minareli Medrese', 'Kütahya\'da gökbilim çalışmalarıyla tanınan Vacidiye Medresesi', 'Mardin yamaçlarında ovaya hâkim yükselen Zinciriye Medresesi'], 'Osmanlı-Karamanoğlu hanedan evliliğinin mimari nişanesi olan Karaman Hatuniye Medresesi, muhteşem mermer taç kapısıyla Beylikler dönemi taş işçiliğinin şaheserlerindendir.'),
  ('Ermenek\'te Emir Musa Bey tarafından 1339 yılında inşa ettirilen \'Tol Medrese\', Karamanoğlu eğitim ve mimari tarihinde hangi öncü konuma sahiptir?', 'Karamanoğulları Beyliği\'nin inşa ettirdiği ilk büyük medrese olması', ['Anadolu\'da tamamen çivisiz ahşap kütüklerle yapılan tek okul olması', 'Yalnızca denizcilik ve haritacılık dersleri için kurulmuş bulunması', 'İçinde ilk kez matbaa harfleriyle Türkçe kitap basılmış olması'], 'Karaman\'ın Ermenek ilçesindeki Tol Medrese (1339), Karamanoğullarının ilk başkenti çevresinde kurdukları ilk anıtsal yükseköğretim kurumudur.'),
  ('Kütahya\'da Germiyanoğulları döneminde 1314 yılında Müderris Abdülvâcid bin Mehmed adına inşa edilen ve aydınlık feneri altında gözlem kuyusu bulunan astronomi ağırlıklı medrese hangisidir?', 'Vâcidiye Medresesi', ['Eğirdir merkezde kervansaraydan dönüştürülen Dündar Bey Medresesi', 'Milas yakınlarındaki Beçin Kalesi\'nde yükselen Ahmet Gazi Medresesi', 'Kayseri\'de tıp eğitimi veren Gevher Nesibe Çifte Medresesi'], 'Ünlü astronom ve fıkıh bilgini Mevlânâ Abdülvâcid\'in ders verdiği Kütahya Vâcidiye Medresesi, Kırşehir Cacabey Medresesi gibi gökbilim araştırmalarıyla tanınmıştır.'),
  ('Germiyanoğlu Süleyman Şah\'ın nişancısı ve defterdarı olup \'Hurşîdnâme\', \'Marzubânnâme Tercümesi\' ve \'Kenzü\'l-Küberâ\' adlı devlet yönetimi kitabını akıcı bir Türkçeyle yazan müellif kimdir?', 'Şeyhoğlu Mustafa', ['Makâlât adlı eseriyle dört kapıyı anlatan Hacı Bektaş-ı Velî', 'Selçuklu tarihini Farsça olarak derleyen Münşî İbn Bîbî', 'Müzik makamlarını sistemleştiren Abdülkadir Merâgî'], 'Germiyanoğulları sarayının Anadolu Türkçesi edebiyatındaki öncülüğünü kanıtlayan Şeyhoğlu Mustafa, telif ve tercüme eserleriyle 14. yüzyıl nesir ve nazmının kurucularındandır.'),
  ('Ünlü Faslı seyyah İbn Battuta\'nın 1330\'lu yıllarda Batı Anadolu gezisi sırasında Birgi ve yazlık yaylada ziyaret ederek cömertliğini, âlimlere saygısını ve sarayına düşen göktaşını incelettiğini anlattığı hükümdar kimdir?', 'Aydınoğlu Mehmed Bey', ['Kastamonu\'da külliye kurduran Candaroğlu İsmail Bey', 'Adana Ulu Camii\'ni tamamlatan Ramazanoğlu Piri Paşa', 'Sivas ve Kayseri\'de düzen kuran Alaeddin Eretna Bey'], 'İbn Battuta Seyahatnamesi\'nde Aydınoğlu Mübarizeddin Mehmed Bey\'in Birgi\'deki müderrislere gösterdiği hürmet ve Birgi dışına düşen demir göktaşını taş ustalarına dövdürme deneyi ayrıntılı biçimde anlatılır.'),
  ('İzmir\'in Ödemiş ilçesine bağlı Birgi\'de 1312 yılında Aydınoğlu Mehmed Bey tarafından yaptırılan \'Birgi Ulu Camii\' özellikle Muzafferüddin bin Abdülvâhid imzalı hangi ahşap şaheseriyle tanınır?', 'Çivisiz gerçek kündekârî tekniğiyle yapılmış ceviz ağacı minberiyle', ['Altın varak kaplamalı üç katlı hükümdar tahtı mahfiliyle', 'Sedef kakmalı sekizgen fildişi vaaz kürsüsü kaplamasıyla', 'Gemi direklerinden yontulmuş kırk adet boyalı tavan sütunuyla'], 'Birgi Ulu Camii\'nin 3000\'den fazla ahşap parçanın tek bir çivi çakılmadan geometrik yıldızlarla birleştirildiği ceviz minberi ve pencere kanatları Beylikler devri ahşap sanatının zirvesidir.'),
  ('Manisa\'da Sipil Dağı eteğinde Saruhanoğlu İshak Bey tarafından 1366-1376 yıllarında Mimar Emet bin Osman\'a yaptırılan \'Manisa Ulu Camii ve Medresesi\' Osmanlı mimarisindeki hangi ünlü esere doğrudan ilham vermiştir?', 'Edirne Üç Şerefeli Cami\'ye', ['Bursa\'daki çok kubbeli Ulu Cami\'ye', 'İstanbul\'daki Sultan Ahmet Camii\'ne', 'Amasya\'daki II. Bayezid Külliyesi\'ne'], 'Mihrap önünde sekizgen ayaklara oturan geniş kubbesi ve revaklı iç avlusuyla Manisa Ulu Camii, II. Murad\'ın yaptırdığı Edirne Üç Şerefeli Cami\'nin (merkezi kubbeye geçişin) öncü prototipidir.'),
  ('Aydın\'ın Söke-Didim arasındaki Balat (antik Miletos) yerleşiminde Menteşeoğlu İlyas Bey tarafından 1404 yılında yaptırılan \'İlyas Bey Camii\' özellikle hangi sanatsal niteliğiyle Avrupa Kültürel Miras ödülü dahi almıştır?', 'Dantel gibi oyulmuş mermer cephesi ve renkli taş kakmalı mihrap işçiliğiyle', ['Dört köşesinde yükselen kırk metrelik sırlı tuğla minareleriyle', 'Hiç taş kullanılmadan sedir ağacı kütükleriyle çatılmış kubbesiyle', 'Duvarlarını kaplayan av sahneli yedi renkli mînâî saray çinileriyle'], 'Antik Milet kalıntılarındaki kaliteli mermerlerin yeniden işlenmesiyle kurulan Balat İlyas Bey Külliyesi (1404), Beylikler dönemi mermer oymacılığının ve tek kubbeli cami estetiğinin başyapıtıdır.'),
  ('Candaroğullarının son dönem hükümdarlarından olup Fatih Sultan Mehmed ile ilmi dostluk kuran, Kastamonu\'da büyük bir külliye yaptırırken bizzat kendisi de \'Hulviyyât-ı Şâhî\' adlı kapsamlı Türkçe fıkıh eserini yazan âlim bey kimdir?', 'Candaroğlu İsmail Bey', ['Babasının tahtına karşı Osmanlı\'ya sığınan Kasım Bey', 'Kötürüm lakabıyla tanınan Celâleddin Bayezid Bey', 'Eflani merkezli ilk kuruluşu gerçekleştiren Yaman Candar'], '1461\'de Trabzon seferi sırasında Sinop ve Kastamonu\'yu savaşsız biçimde Fatih Sultan Mehmed\'e teslim eden İsmail Bey, bizzat telif ettiği Türkçe \'Hulviyyât\' eseri ve Kastamonu İsmail Bey Külliyesi ile tanınır.'),
  ('Hamitoğullarının Antalya merkezli güney kolu olarak tarih sahnesine çıkan \'Tekeoğulları Beyliği\'nde Kıbrıs Haçlı Kralı Pierre de Lusignan\'ın 1361\'de işgal ettiği Antalya\'yı on iki yıllık kuşatma ve mücadelenin ardından 1373\'te Haçlılardan geri alan hükümdar kimdir?', 'Mübarizeddin Mehmed Bey', ['Alanya kalesini Ermenilerden teslim alan Alaeddin Keykubad', 'İzmir limanında Haçlı şövalyeleriyle çarpışan Gazi Umur Bey', 'Rodos adasına çıkarma hazırlığı yürüten Menteşeoğlu Orhan Bey'], '\'Zincirkıran\' lakabıyla da anılan Tekeoğlu Mübarizeddin Mehmed Bey, 1373\'te Antalya liman zincirlerini ve surlarını aşarak kenti Kıbrıs Haçlı işgalinden kurtarmıştır.'),
  ('Kayseri\'de Alâeddin Eretna tarafından eşi Suli Paşa için 1339 yılında yüksek kayalık üzerine yaptırılan ve dıştan kale burçlu küçük bir sarayı andıran sekizgen kümbetli yapı hangisidir?', 'Köşk Medrese', ['Sivas\'ta Eretna\'nın oğluna ait olan Güdük Minare', 'Niğde\'de Akmedrese adıyla bilinen Karamanoğlu yapısı', 'Kırşehir\'de gökbilim rasathanesi olan Cacabey Medresesi'], 'Kayseri\'deki Köşk Medrese, etrafını saran yüksek mazgallı avlu duvarları ve ortasındaki sekizgen Eretna hanedan kümbetiyle Tercan Mama Hatun şemasını andıran özgün bir Eretna eseridir.'),
  ('Dulkadiroğlu hükümdarı Alaüddevle Bozkurt Bey tarafından hazırlanıp Osmanlı döneminde de Maraş-Bozok sancağında uzun süre yürürlükte kalan \'Alaüddevle Bey Kanunnamesi\' hangi hukuk geleneğinin önemli bir belgesidir?', 'Örfi Türk ceza ve vergi hukuku ile şer\'i kuralların sentezinin', ['Venedik deniz ticaret mahkemelerinden çevrilen liman yasalarının', 'Cengiz Han Yasası\'nın hiçbir değişiklik yapılmadan uygulanmasının', 'Bizans tarım kanunlarının Grekçe aslıyla yürürlükte tutulmasının'], 'Bozok ve Maraş Türkmenlerinin toplumsal yapısına uygun arazi, vergi ve ceza hükümleri içeren \'Alaüddevle Bey Kanunnamesi\', Osmanlı sancak kanunnamelerine doğrudan kaynaklık etmiştir.'),
  ('Sinop merkezli kurulan \'Pervaneoğulları Beyliği\'nin son hükümdarı olup Trabzon Rumları ile Kırım\'daki Kefe Cenevizlilerine karşı düzenlediği gözü pek deniz baskınlarıyla efsaneleşen Türk denizcisi kimdir?', 'Gazi Çelebi', ['Ege adalarında Venedik filolarını vuran Gazi Umur Bey', 'Gelibolu yarımadasına ilk çıkarmayı yapan Süleyman Paşa', 'Midilli ve Sakız adalarını Bizans\'tan alan Çaka Bey'], 'Muineddin Pervane\'nin soyundan gelen Sinop Hâkimi Gazi Çelebi (ö. 1322?), Karadeniz\'de Ceneviz kalyonlarını delip batırmasıyla ünlü bir deniz gazisidir; vefatından sonra Sinop Candaroğullarına geçmiştir.'),
  ('Denizli (Ladik) ve çevresinde kurulan \'İnançoğulları Beyliği\' (Ladik Beyliği) döneminde İnanç Bey ve oğlu Murad Arslan adına kaleme alınan \'Fâtiha ve İhlâs Tefsirleri\' kültür tarihi açısından neyin kanıtıdır?', 'Anadolu\'daki en erken satır arası ve müstakil Türkçe Kur\'an tefsiri çalışmalarının beylik himayesinde başladığının', ['Denizli bölgesinde Arap alfabesinin bırakılıp Uygur harflerinin resmi yazı yapıldığının', 'Medreselerde fıkıh ve hadis derslerinin kaldırılıp yalnızca şiir okutulduğunun', 'İnançoğulları Beyliği\'nin Mısır Memlük halifeliğini Denizli\'ye taşıdığının'], 'İbn Battuta\'nın altın sırmalı pamuklu dokumalarını ve Ahilerini övdüğü Denizli\'de (Ladik), İnançoğlu Murad Arslan Bey\'in emriyle yazılan Türkçe tefsirler 14. yüzyıl Türk din ve dil tarihinin anıt eserleridir.'),
  ('Kastamonu\'da Candaroğullarından önce 13. yüzyılda hüküm süren \'Çobanoğulları Beyliği\'nde Muzaffereddin Yavlak Arslan ve oğlu Mahmud Bey\'in hem Türkmen uç gazilerini sevk etmesi hem de Mevlânâ ve Şirazlı Kutbüddin gibi bilginlerle mektuplaşıp eserler ithaf alması nasıl değerlendirilir?', 'Uç beyliği gaza dinamizmi ile yüksek şehirli İslam ilim kültürünün Kastamonu\'da bütünleştiği biçiminde', ['Çobanoğullarının Bizans sınırındaki savaşları bırakıp tamamen inzivaya çekildiği şeklinde', 'Kastamonu şehrinin yalnızca İran\'dan sürgün edilen memurların kampı olduğu biçiminde', 'Uç bölgelerinde Türkçe konuşulmasının saray görevlilerince yasaklandığı şeklinde'], 'Hüsameddin Çoban\'ın kurduğu Çobanoğulları Beyliği bir yandan Karadeniz-Bizans ucunda gaza yaparken (Osman Gazi\'nin ilk dönem üst uçbeyi konumu), diğer yandan Kastamonu\'yu hastane ve kütüphanelerle bilimsel bir merkez yapmıştır.'),
  ('Niğde şehir merkezinde Karamanoğlu Alâeddin Ali Bey\'in oğlu Mehmed Bey tarafından 1409 yılında yaptırılan ve cephesinin üst katında sokağa bakan çift kemerli revaklı galerisiyle diğer tüm Anadolu medreselerinden ayrılan yapı hangisidir?', 'Niğde Akmedrese', ['Karaman\'da yükselen Nefise Sultan Hatuniye Medresesi', 'Ermenek\'te kurulan Emir Musa Bey Tol Medresesi', 'Konya\'da çinileriyle tanınan Celaleddin Karatay Medresesi'], 'Ak mermer görünümlü kesme taş taç kapısı ve üst katında dış cepheye açılan gotik/Kıbrıs-Lüzinyan kemer çağrışımlı ikiz revak pencereleriyle Niğde Akmedrese (1409), iki katlı Anadolu medreselerinin en özgün örneklerindendir.'),
  ('Karaman\'da Karamanoğlu II. İbrahim Bey tarafından 1432 yılında yaptırılan \'İbrahim Bey İmareti\'nin çini mihrabı ile İstanbul Çinili Köşk\'e nakledilen bu mihrabın Beylikler dönemi sanatındaki yeri nedir?', 'Selçuklu mozaik çini geleneğini çok renkli sır üstü ve kabartma çini ustalığıyla Osmanlı\'ya bağlaması', ['Avrupa\'dan ithal edilen porselen tabakların duvar harcına gömülmesiyle oluşturulması', 'Üzerinde hiçbir yazı bulunmayıp yalnızca savaş sahnelerinin resmedilmiş olması', 'Tamamen sırsız pişmiş topraktan yapılıp kireç badana ile beyaza boyanması'], 'Osmanlı Çelebi Mehmed dönemindeki Bursa Yeşil Cami çinilerini yapan \'Tebrizli ustalar\' ekolüyle çağdaş olan Karaman İbrahim Bey İmareti çini mihrabı, 15. yüzyıl Türk çini sanatının şaheserlerindendir.'),
  ('Milas\'ta Menteşe Valisi Hoca Firuz Bey tarafından 1394 yılında Mimar Hasan bin Abdullah\'a yaptırılan \'Firuz Bey Camii\' çatısının kurşun levhalarla kaplanması nedeniyle yerel halk arasında hangi adla tanınmıştır?', 'Kurşunlu Cami', ['Alaca Mescit', 'Yeşil İmaret', 'Tahta Minare'], 'Bursa\'daki erken Osmanlı \'zaviyeli (ters T planlı)\' camileriyle büyük benzerlik gösteren Milas Firuz Bey Camii (1394), mermer işçiliği ve kurşun kaplı kubbeleriyle \'Kurşunlu Cami\' adını almıştır.'),
  ('Beylikler döneminde Menteşe, Aydın ve Saruhan limanlarında basılan ve Venedik altın dukası ya da Napoli-Anjou \'gigliato\' gümüş sikkelerini taklit eden Latince yazılı paraların (\'gigliati\') darbedilmesinin ticari nedeni nedir?', 'Batılı tüccarların Ege pazarlarında alışkın oldukları para birimiyle alışverişi hızlandırmak', ['Türkmen beylerinin Papa\'ya bağlılıklarını sikkeler üzerinden ilan etmek istemesi', 'Anadolu\'da Arap harflerini maden kalıplara kazıyacak hakkâk ustası kalmaması', 'Venedik donanmasının Türkçe ve Arapça yazılı paralara denizde el koyması'], 'Tıpkı daha önce Artukluların figürlü sikkelerinde olduğu gibi, Ayasuluk (Theologo), Balat (Palatia) ve Manisa darphanelerinde İtalyan tüccarlar için gümüş \'gigliato\' basılması Batı Anadolu beyliklerinin uluslararası ticarete ne denli entegre olduğunu kanıtlar.'),
  ('Orta Karadeniz\'de (Canik bölgesi: Niksar, Çarşamba, Terme, Samsun kırsalı) Taceddin Bey tarafından kurulan ve Trabzon Rum İmparatorluğu ile hem savaşıp hem de hanedan evlilikleri kuran Türkmen beyliği hangisidir?', 'Tâceddinoğulları', ['Göller yöresinde egemen olan Hamitoğulları', 'Muğla ve Beçin merkezli Menteşeoğulları', 'Maraş ve Elbistan yaylasındaki Dulkadiroğulları'], '14. yüzyılda Canik (Samsun-Ordu-Niksar arası) bölgesinde kurulan Tâceddinoğulları (Canik beyliklerinden en önemlisi), Trabzon Rum İmparatoru III. Aleksios\'un kızı Evdokia ile Taceddin Bey\'in evliliğiyle Karadeniz siyasetinde denge unsuru olmuştur.'),
  ('Ankara\'da Ahi Şerefeddin (Arslanhane) Camii\'nin 1290 yılında Ahi Hüsameddin ve kardeşi Hasaneddin tarafından onarılıp yeniden inşası sırasında mihrabında kullanılan malzeme kombinasyonu neden sanat tarihinde özeldir?', 'Firuze-patlıcan moru mozaik çini ile alçı kabartma tekniğini anıtsal boyutta birleştirmesiyle', ['Tamamen dökme tunç levhaların birbirine perçinlenmesiyle yapılmış olmasıyla', 'Roma döneminden kalma cam şişelerin eritilerek duvara sıvanmasıyla', 'Hiçbir süsleme kullanılmadan düz siyah bazalt taşından örülmesiyle'], 'Yirmi dört ahşap sütunlu Ankara Arslanhane (Ahi Şerefeddin) Camii, görkemli çini-alçı mihrabı ve ceviz kündekârî minberiyle Ahi teşkilatının imar gücünü yansıtan en büyük Selçuklu-Ahi mirasıdır.'),
  ('Kahramanmaraş\'ın Elbistan ilçesinde Dulkadiroğlu Şehsuvar Bey veya Alaüddevle Bozkurt Bey dönemlerinde son şeklini alan \'Elbistan Ulu Camii\' dört yarım kubbeyle desteklenen merkezi kubbesiyle hangi etkileşimi gösterir?', 'Klasik Osmanlı merkezi kubbeli cami mimarisinin 16. yüzyıl başında Dulkadir topraklarına yansımasını', ['Büyük Selçukluların İran\'daki kerpiç dört eyvanlı cami tipinin aynen korunmasını', 'Gotik katedrallerdeki uçan payanda ve gül pencere sisteminin uygulanmasını', 'Karadeniz yaylalarındaki çivisiz ahşap çantı cami geleneğinin taşla taklit edilmesini'], '1515 sonrası onarımlarla da bütünleşen Elbistan Ulu Camii, Dulkadirli beyliğinin Osmanlı saray mimarlığıyla (Şehzade/Fatih-Bayezid ekolü öncülleriyle) girdiği yakın sanatsal etkileşimin anıtsal örneğidir.'),
  ('Adana\'da haçlı/Ermeni döneminden kalma eski bir kilisenin 1501 yılında Ramazanoğlu Halil Bey tarafından eklemeler ve görkemli bir taç kapıyla camiye dönüştürülmesi ve önündeki pazar yerinden ötürü aldığı ad hangisidir?', 'Adana Yağ Camii', ['Tarsus merkezde yükselen Kırkkaşık Bedesteni Camii', 'Mersin Silifke kalesi eteğindeki Reşadiye Camii', 'Antakya çarşısında yer alan Habîb-i Neccâr Camii'], 'Önünde kurulan yağ pazarından dolayı \'Yağ Camii\' adını alan yapı, Ramazanoğlu Halil Bey ve oğlu Piri Paşa\'nın Selçuklu üslubunu yaşatan sarı-siyah taşlı taç kapısıyla Çukurova Beylikler mimarisinin önemli bir örneğidir.'),
  ('Sivas merkezde Eretna Bey\'in büyük oğlu Şeyh Hasan Bey için 1347 yılında yaptırılan, kare taş kaide üzerinde tuğla üçgenlerle yükselen silindirik gövdesi sebebiyle halkın bu adla andığı anıt mezar hangisidir?', 'Güdük Minare', ['Erzurum\'da üçlü grup halinde duran Emir Saltuk Kümbeti', 'Kayseri\'de Hunat Külliyesi içindeki Mahperi Hatun Kümbeti', 'Ahlat\'ta Van Gölü kıyısında yükselen Ulu Kümbet'], 'D부-dış görünümü kalın ve kısa kalmış bir minareyi andırdığı için Sivas halkının \'Güdük Minare\' adını verdiği Şeyh Hasan Bey Kümbeti (1347), Eretna dönemi taş-tuğla geçiş tekniğinin en ilginç eseridir.'),
  ('15. yüzyılda Menteşeoğlu İlyas Bey adına Şirvanlı Mahmud bin İlyas tarafından kaleme alınan \'Kitâbü\'l-İlyâsiyye\' ve Kastamonu\'da Candaroğlu İsfendiyar Bey adına Sinoplu Mümin bin Mukbil\'in yazdığı \'Miftâhu\'n-Nûr ve Hazâinü\'s-Sürûr\' hangi bilim dalına aittir?', 'Tıp ve göz hastalıkları bilimine', ['Gemi inşası ve pusula kullanımına', 'Top dökümü ve kale tahkimatına', 'Miras hukuku ve arazi ölçümüne'], 'Beylik saraylarında tıp araştırmaları büyük destek görmüş; Sinoplu Mümin bin Mukbil\'in göz anatomisi ve katarakt tedavisini Türkçe anlattığı \'Miftâhu\'n-Nûr\' eseri devrinin en ileri oftalmoloji kitaplarından biri olmuştur.'),
  ('Karamanoğulları tarihini efsanevi unsurlarla harmanlayarak akıcı bir halk Türkçesiyle anlatan ve Karaman beylerinin Selçuklu sultanlarıyla ilişkilerine ışık tutan \'Karamannâme\' adlı eserin müellifi kimdir?', 'Şikârî', ['Aksarayî', 'Râvendî', 'Neşrî'], '16. yüzyılda Yarcanî\'nin Farsça Şehnâme\'sini Türkçeye uyarlayıp genişleten Şikârî\'nin \'Karamannâme\' (Karamanoğulları Tarihi) adlı eseri, beyliğin kendi bakış açısını yansıtan temel kaynaktır.'),
  ('Beylikler devrinde Kütahya, İznik ve Karaman atölyelerinde üretilen \'Milet işi\' olarak adlandırılmış kırmızı hamurlu, beyaz astarlı ve kobalt mavisi-firuze desenli seramiklerin İznik kazıları sonucunda gerçek üretim merkezi neresi çıkmıştır?', 'İznik ve Kütahya çini fırınları', ['Rodos Şövalyelerinin ada kalelerindeki İtalyan atölyeleri', 'Şam ve Halep çarşılarındaki Memlük cam imalathaneleri', 'Tebriz sarayındaki İlhanlı porselen ustalarının ocakları'], 'İlk kez Milet (Balat) kazılarında bolca bulunduğu için \'Milet işi\' adı takılan 14.-15. yüzyıl erken Beylik-Osmanlı seramiklerinin asıl üretim merkezinin İznik (ve kısmen Kütahya) fırınları olduğu arkeolojik fırın buluntularıyla kanıtlanmıştır.'),
];
